/**
 * Modelo de custo de ingrediente — ESPELHO EXATO da função `compute_item_cost`
 * do banco (Postgres), que é a fonte da verdade (triggers recomputam custo em
 * INSERT/UPDATE/DELETE de ficha_tecnica_itens). O frontend usa isto só para
 * EXIBIR custo ao vivo enquanto o usuário edita (antes do trigger persistir).
 *
 * Regra (igual ao banco):
 *   custo_item = preco_custo × quantidade × ratio(unidade_item → unidade_compra)
 *   - pares padrão (g↔kg, mL↔L, mg↔g): conversão física; fator_conversao IGNORADO
 *   - pares não-padrão (espiga, pack, un…): ratio = 1 / fator_conversao
 *   sub-receita: (custo_calculado / rendimento_quantidade) × quantidade
 *   esboço:      preco_unitario_esboco × quantidade
 */

export interface CustoFichaRef {
  id: number;
  custo_calculado: number;
  rendimento_quantidade: number;
}

interface InsumoCusto {
  id: number;
  preco_custo: number | null;
  unidade_compra?: string | null;
  fator_conversao?: number | null;
}

interface ItemCusto {
  insumo_id: number | null;
  sub_ficha_id: number | null;
  quantidade: number;
  unidade: string;
  preco_unitario_esboco: number | null;
}

/** Conversões padrão (físicas) — mesmas do banco. Chave: `${unidadeItem}|${unidadeCompra}`. */
const RATIOS_PADRAO: Record<string, number> = {
  'g|kg': 0.001,
  'kg|g': 1000,
  'ml|l': 0.001,
  'l|ml': 1000,
  'mg|g': 0.001,
  'g|mg': 1000,
};

/** True se o par (unidade do item, unidade de compra) é convertível automaticamente. */
export const ehParPadrao = (unidadeItem?: string | null, unidadeCompra?: string | null): boolean => {
  const uf = (unidadeItem ?? '').toLowerCase();
  const ui = (unidadeCompra ?? '').toLowerCase();
  return uf === ui || `${uf}|${ui}` in RATIOS_PADRAO;
};

/**
 * Fator que converte a quantidade (na unidade do item/produção) para a unidade de
 * compra, replicando o banco. Para pares não-padrão usa 1/fator_conversao.
 */
export const ratioParaUnidadeCompra = (
  unidadeItem?: string | null,
  unidadeCompra?: string | null,
  fatorConversao?: number | null,
): number => {
  const uf = (unidadeItem ?? '').toLowerCase();
  const ui = (unidadeCompra ?? '').toLowerCase();
  if (uf === ui) return 1;
  const padrao = RATIOS_PADRAO[`${uf}|${ui}`];
  if (padrao != null) return padrao;
  return fatorConversao && fatorConversao > 0 ? 1 / fatorConversao : 1;
};

/** Preço por unidade de produção (= preço de compra convertido). Usado em exibições. */
export const precoPorUnidadeProducao = (insumo: {
  preco_custo: number | null;
  unidade_producao?: string | null;
  unidade_compra?: string | null;
  fator_conversao?: number | null;
}): number =>
  (Number(insumo.preco_custo) || 0) *
  ratioParaUnidadeCompra(insumo.unidade_producao, insumo.unidade_compra, insumo.fator_conversao);

/** Custo de uma linha de ingrediente (insumo / sub-receita / esboço). */
export const custoItemFicha = (
  item: ItemCusto,
  insumos: InsumoCusto[],
  fichas: CustoFichaRef[] = [],
): number => {
  if (item.insumo_id) {
    const ins = insumos.find((i) => i.id === item.insumo_id);
    if (!ins || ins.preco_custo == null) return 0;
    const ratio = ratioParaUnidadeCompra(item.unidade, ins.unidade_compra, ins.fator_conversao);
    return (Number(ins.preco_custo) || 0) * item.quantidade * ratio;
  }
  if (item.sub_ficha_id) {
    const sub = fichas.find((f) => f.id === item.sub_ficha_id);
    if (!sub || sub.rendimento_quantidade <= 0) return 0;
    return (sub.custo_calculado / sub.rendimento_quantidade) * item.quantidade;
  }
  return (item.preco_unitario_esboco ?? 0) * item.quantidade;
};

/** Custo total dos ingredientes de uma ficha. */
export const calcularCustoFicha = (
  itens: ItemCusto[],
  insumos: InsumoCusto[],
  fichas: CustoFichaRef[] = [],
): number => itens.reduce((total, item) => total + custoItemFicha(item, insumos, fichas), 0);

