-- MINIS: casquinha 12g choc 51% + 25g recheio (rend 1 un)
DO $$
DECLARE
  m RECORD; v_fid BIGINT; v_choc BIGINT; v_rec BIGINT;
BEGIN
  SELECT id INTO v_choc FROM insumos WHERE nome='CHOCOLATE 52 SEM AÇUCAR 25 KG' ORDER BY id LIMIT 1;
  FOR m IN SELECT * FROM (VALUES
    ('Mini Pistache','Brigadeiro de Pistache'),
    ('Mini Prestígio','Brigadeiro de Prestígio'),
    ('Mini Brigadeiro','Brigadeiro Preto Low Carb'),
    ('Mini Torta de Limão','Mousse de Limão'),
    ('Mini Caramelo Salgado','Caramelo Salgado'),
    ('Mini Mousse Maracujá','Mousse de Maracujá'),
    ('Mini Brigadeiro Vegano','Brigadeiro Preto Vegano'),
    ('Mini Pistache Vegano','Brigadeiro Pistache Vegano'),
    ('Mini Café','Creme de Cappuccino')
  ) AS t(nome, recheio) LOOP
    INSERT INTO fichas_tecnicas (nome,versao,status,rendimento_quantidade,rendimento_unidade,custo_calculado,observacoes)
      SELECT m.nome,1,'aprovada',1,'un',0,'auto-custo NF 2026-06 (mini: casquinha 12g + recheio 25g)'
      WHERE NOT EXISTS (SELECT 1 FROM fichas_tecnicas WHERE nome=m.nome);
    SELECT id INTO v_fid FROM fichas_tecnicas WHERE nome=m.nome ORDER BY id LIMIT 1;
    SELECT id INTO v_rec FROM fichas_tecnicas WHERE nome=m.recheio ORDER BY id LIMIT 1;
    DELETE FROM ficha_tecnica_itens WHERE ficha_tecnica_id=v_fid;
    INSERT INTO ficha_tecnica_itens (ficha_tecnica_id,tipo,insumo_id,sub_ficha_id,quantidade,unidade,ordem) VALUES
      (v_fid,'insumo',v_choc,NULL,12,'g',1),
      (v_fid,'sub_receita',NULL,v_rec,25,'g',2);
  END LOOP;
END $$;

