-- CMV da BOLA 100g = custo/(rend_L * 10), pra todos os gelatos/sorbets linkados
UPDATE produtos_master pm SET preco_custo = (
  SELECT ROUND(ft.custo_calculado/(ft.rendimento_quantidade*10),2)
  FROM fichas_tecnicas ft WHERE ft.produto_master_id=pm.id AND ft.rendimento_unidade IN ('L','kg')
    AND (ft.nome LIKE 'Gelato%' OR ft.nome LIKE 'Sorbet%') ORDER BY ft.id LIMIT 1)
WHERE pm.id IN (SELECT produto_master_id FROM fichas_tecnicas WHERE produto_master_id IS NOT NULL AND rendimento_unidade IN ('L','kg') AND (nome LIKE 'Gelato%' OR nome LIKE 'Sorbet%'));
