/**
 * @module useProductSalesData
 *
 * Hook memoizado que processa histórico de vendas a partir de JSON
 * estático, calculando estatísticas por dia da semana, tendência
 * e sugestão de quantidade para cada produto.
 */

import { useMemo } from 'react';
import { wideDebug } from '@/shared/lib/telemetry/wide-events';
import salesDataRaw from '@/shared/data/sales_history.json';
import {
  startOfDay,
  parseISO,
  differenceInDays,
  endOfDay,
  subDays,
} from 'date-fns';

/** Registro de venda diária com quantidade, dia da semana e preço médio. */
export interface DailySale {
  date: string;
  quantity: number;
  weekday: string;
  avgPrice?: number;
  total?: number;
}

/** Estatísticas de venda para um dia da semana: média, min, max e desvio padrão. */
export interface WeekdayStats {
  avg: number;
  min: number;
  max: number;
  stdDev: number;
  count: number;
}

/** Análise completa de um produto: stats por dia, tendência e sugestão de pedido. */
export interface ProductAnalysis {
  id: string;
  name: string;
  code: string;
  category: string;
  stats: Record<string, WeekdayStats>;
  overallAvg: number;
  periodAvg: number;
  suggestion: number;
  trending: 'up' | 'down' | 'stable';
  salesHistory: DailySale[];
}

interface ProductHistory {
  productName: string;
  productCode: string;
  category: string;
  categoryType?: string;
  storeName: string;
  salesHistory: DailySale[];
}

const WEEKDAYS = [
  'segunda-feira',
  'terça-feira',
  'quarta-feira',
  'quinta-feira',
  'sexta-feira',
  'sábado',
  'domingo',
];

interface UseProductSalesDataProps {
  selectedStore?: string | null;
  targetWeekday?: string;
  daysToAnalyze?: number;
}

/**
 * Processa histórico de vendas JSON e calcula estatísticas por produto.
 *
 * Filtra por loja, agrupa vendas por dia da semana dentro do período
 * de análise e calcula média, desvio padrão, tendência e sugestão
 * de quantidade (média + 0.5 * desvio) para o dia alvo.
 *
 * @param selectedStore  - Nome da loja para filtro (opcional).
 * @param targetWeekday  - Dia da semana alvo (padrão: hoje).
 * @param daysToAnalyze  - Janela de dias para análise (padrão: 30).
 * @returns Lista de produtos analisados e dia da semana efetivo.
 */
export function useProductSalesData({
  selectedStore,
  targetWeekday,
  daysToAnalyze = 30,
}: UseProductSalesDataProps = {}) {
  // Default to today's weekday if not provided
  const effectiveWeekday =
    targetWeekday ||
    new Date().toLocaleDateString('pt-BR', { weekday: 'long' });

  const processedData = useMemo(() => {
    let rawData = salesDataRaw as ProductHistory[];

    // Filter by store if selected
    if (selectedStore) {
      wideDebug('produtos.sales_data_filter', `Filtrando por loja: "${selectedStore}"`, { domain: 'produtos', attributes: { store: selectedStore } });

      // Flexible matching for store name (bidirectional check)
      rawData = rawData.filter((p) => {
        const jsonStore = p.storeName.toLowerCase();
        const selected = selectedStore.toLowerCase();
        const match =
          jsonStore.includes(selected) || selected.includes(jsonStore);
        if (!match && Math.random() < 0.001) {
          wideDebug('produtos.sales_data_mismatch', `Mismatch: JSON "${p.storeName}" vs Selected "${selectedStore}"`, { domain: 'produtos', attributes: { jsonStore: p.storeName, selectedStore } });
        }
        return match;
      });
      wideDebug('produtos.sales_data_filtered', `Encontrados ${rawData.length} produtos após filtro`, { domain: 'produtos', attributes: { count: rawData.length, store: selectedStore } });
    }

    // Determine date range based on latest available data
    const allDates: string[] = [];
    rawData.forEach((product) => {
      product.salesHistory.forEach((sale) => {
        allDates.push(sale.date);
      });
    });

    const lastDataDate =
      allDates.length > 0
        ? startOfDay(parseISO(allDates.sort((a, b) => b.localeCompare(a))[0]))
        : startOfDay(new Date());

    const startDate = subDays(lastDataDate, daysToAnalyze);

    return rawData.map((product) => {
      const byWeekday: Record<string, number[]> = {};
      WEEKDAYS.forEach((d) => (byWeekday[d] = []));

      const sortedHistory = [...product.salesHistory].sort((a, b) =>
        b.date.localeCompare(a.date),
      );

      // Filter history by date range
      const historyInPeriod = sortedHistory.filter((sale) => {
        const saleDate = parseISO(sale.date);
        return saleDate >= startDate && saleDate <= endOfDay(lastDataDate);
      });

      const sumPeriod = historyInPeriod.reduce(
        (acc, curr) => acc + curr.quantity,
        0,
      );
      const daysInPeriod = Math.max(
        differenceInDays(lastDataDate, startDate) + 1,
        1,
      );
      const periodAvg = sumPeriod / daysInPeriod;

      // Populate weekday stats
      historyInPeriod.forEach((sale) => {
        if (byWeekday[sale.weekday])
          byWeekday[sale.weekday].push(sale.quantity);
      });

      const stats: Record<string, WeekdayStats> = {};
      let totalQty = 0,
        totalDays = 0;

      WEEKDAYS.forEach((day) => {
        const quantities = byWeekday[day];
        const count = quantities.length;
        if (count === 0) {
          stats[day] = { avg: 0, min: 0, max: 0, stdDev: 0, count: 0 };
          return;
        }
        const sum = quantities.reduce((a, b) => a + b, 0);
        const avg = sum / count;
        const variance =
          quantities.reduce((acc, val) => acc + Math.pow(val - avg, 2), 0) /
          count;
        stats[day] = {
          avg,
          min: Math.min(...quantities),
          max: Math.max(...quantities),
          stdDev: Math.sqrt(variance),
          count,
        };
        totalQty += sum;
        totalDays += count;
      });

      const overallAvg = totalDays > 0 ? totalQty / totalDays : 0;
      let trending: 'up' | 'down' | 'stable' = 'stable';
      if (periodAvg > overallAvg * 1.1) trending = 'up';
      else if (periodAvg < overallAvg * 0.9) trending = 'down';

      const targetStats = stats[effectiveWeekday];
      // Suggestion logic: Avg + 0.5 * StdDev to cover volatility
      const suggestion = targetStats
        ? Math.ceil(targetStats.avg + targetStats.stdDev * 0.5)
        : 0;

      return {
        id: product.productCode,
        name: product.productName,
        code: product.productCode,
        category: product.category,
        stats,
        overallAvg,
        periodAvg,
        suggestion,
        trending,
        salesHistory: sortedHistory,
      } as ProductAnalysis;
    });
  }, [selectedStore, daysToAnalyze, effectiveWeekday]);

  return {
    products: processedData,
    targetWeekday: effectiveWeekday,
  };
}

