245	export default function ProductAnalytics() {
246	  const navigate = useNavigate();
247	  const { toast } = useToast();
248	  const isMobile = useIsMobile();
249	  const { stores, setSelectedStore } = useStore();
250	  const { hasData, applyStoreFilter, storeId, selectedStore } =
251	    useStoreFilter();
252	  const today = new Date();
253	
254	  const [dateRange, setDateRange] = useState<DateRange | undefined>({
255	    from: startOfMonth(today),
256	    to: today,
257	  });
258	  const [viewMode, setViewMode] = useState<'volume' | 'money'>('volume');
259	  const [searchTerm, setSearchTerm] = useState('');
260	  const [isLoading, setIsLoading] = useState(true);
261	  const [movements, setMovements] = useState<AnalyticsMovement[]>([]);
262	  const [products, setProducts] = useState<ProductInfo[]>([]);
263	  const [isLeaving, setIsLeaving] = useState(false);
264	  const [selectedProduct, setSelectedProduct] = useState<string | null>(null);
265	
266	  // Filtros de granularidade: Setor e Categoria
267	  const [selectedSetor, setSelectedSetor] = useState<string>('all');
268	  const [selectedCategoria, setSelectedCategoria] = useState<string>('all');
269	  const [setores, setSetores] = useState<string[]>([]);
270	  const [categorias, setCategorias] = useState<{ id: number; nome: string }[]>(
271	    [],
272	  );
273	
274	  // Fetch Setores e Categorias
275	  useEffect(() => {
276	    const loadFilters = async () => {
277	      try {
278	        // Buscar setores ativos
279	        const { data: setoresData } = await supabase
280	          .from('setores')
281	          .select('nome')
282	          .eq('ativo', true)
283	          .order('nome');
284	
285	        const setoresList = (setoresData || [])
286	          .map((s: any) => s.nome)
287	          .filter((nome: string) => nome && nome.trim() !== '');
288	        setSetores(setoresList);
289	
290	        // Buscar categorias
291	        const { data: categoriasData } = await supabase
292	          .from('categorias')
293	          .select('id, nome')
294	          .order('nome');
295	
296	        setCategorias(categoriasData || []);
297	      } catch (error) {
298	        handleError(error, { domain: 'produtos', operation: 'loadFilters', showToast: false });
299	      }
300	    };
301	    loadFilters();
302	  }, []);
303	
304	  // Fetch Data
305	  useEffect(() => {
306	    const loadData = async () => {
307	      if (!hasData) return;
308	      setIsLoading(true);
309	      try {
310	        // Use standardized view that joins products and stock
311	        const prodQuery = (supabase as any)
312	          .from('vw_produtos_estoque_lojas')
313	          .select(
314	            'id, nome, preco_custo, setor, categoria_id, quantidade_atual',
315	          )
316	          .eq('loja_id', storeId); // Filter by store explicitly as view has loja_id
317	
318	        // prodQuery = applyStoreFilter(prodQuery); // Already filtered by storeId above
319	
320	        const { data: viewData, error: viewError } = await prodQuery;
321	        if (viewError) throw viewError;
322	
323	        const productsWithStock = (viewData || []).map((p: any) => ({
324	          id: p.id,
325	          nome: p.nome,
326	          preco_custo: p.preco_custo,
327	          setor: p.setor,
328	          categoria_id: p.categoria_id,
329	          quantidade_atual: p.quantidade_atual,
330	        }));
331	        setProducts(productsWithStock);
332	
333	        const start = dateRange?.from
334	          ? startOfDay(dateRange.from)
335	          : startOfDay(subDays(today, 30));
336	        const end = dateRange?.to ? endOfDay(dateRange.to) : endOfDay(today);
337	
338	        // Fetch all movements using pagination to bypass Supabase 1000 row limit
339	        const PAGE_SIZE = 1000;
340	        let allMovements: any[] = [];
341	        let page = 0;
342	        let hasMore = true;
343	
344	        while (hasMore) {
345	          const from = page * PAGE_SIZE;
346	          const to = from + PAGE_SIZE - 1;
347	
348	          const { data: movData, error: movError } = await supabase
349	            .from('movimentacoes')
350	            .select(
351	              `
352	                            id,
353	                            tipo_movimentacao,
354	                            quantidade,
355	                            data_movimentacao,
356	                            loja_id,
357	                            produto:produtos_master!inner(nome, categoria:categorias(nome)),
358	                            usuario:usuarios(nome)
359	                        `,
360	            )
361	            .eq('loja_id', storeId)
362	            .gte('data_movimentacao', start.toISOString())
363	            .lte('data_movimentacao', end.toISOString())
364	            .order('data_movimentacao', { ascending: false })
365	            .range(from, to);
366	
367	          if (movError) throw movError;
368	
369	          if (movData && movData.length > 0) {
370	            allMovements = [...allMovements, ...movData];
371	            page++;
372	            hasMore = movData.length === PAGE_SIZE;
373	          } else {
374	            hasMore = false;
375	          }
376	
377	          if (page >= 50) hasMore = false; // Safety limit
378	        }
379	
380	        // Transform to expected format
381	        const transformedMovements: AnalyticsMovement[] = allMovements.map(
382	          (m: any) => ({
383	            movimentacao_id: m.id,
384	            tipo_movimentacao: m.tipo_movimentacao,
385	            produto_nome: m.produto?.nome || 'Desconhecido',
386	            categoria_nome: m.produto?.categoria?.nome || 'Outros',
387	            quantidade: m.quantidade,
388	            data_movimentacao: m.data_movimentacao,
389	            usuario_nome: m.usuario?.nome || 'Sistema',
390	          }),
391	        );
392	        setMovements(transformedMovements);
393	      } catch (error) {
394	        handleError(error, { domain: 'produtos', operation: 'loadAnalytics', showToast: false });
395	        toast({
396	          title: 'Erro ao carregar dados',
397	          description:
398	            (error as any)?.message ||
399	            'Verifique o console para mais detalhes.',
400	          variant: 'destructive',
401	        });
402	      } finally {
403	        setIsLoading(false);
404	      }
405	    };
406	    loadData();
407	    // eslint-disable-next-line react-hooks/exhaustive-deps
408	  }, [hasData, storeId, dateRange]);
409	
410	  // Analytics computations
411	  const analytics = useMemo(() => {
412	    // Filtrar produtos por setor e categoria selecionados
413	    const filteredProducts = products.filter((p) => {
414	      const matchSetor = selectedSetor === 'all' || p.setor === selectedSetor;
415	      const matchCategoria =
416	        selectedCategoria === 'all' ||
417	        p.categoria_id?.toString() === selectedCategoria;
418	      return matchSetor && matchCategoria;
419	    });
420	
421	    const prodMap = new Map<string, ProductInfo>();
422	    filteredProducts.forEach((p) => prodMap.set(p.nome, p));
423	
424	    // Mapear categoria_id para nome
425	    const getCategoriaName = (catId?: number) => {
426	      if (!catId) return 'Outros';
427	      const cat = categorias.find((c) => c.id === catId);
428	      return cat?.nome || 'Outros';
429	    };
430	
431	    const productStats: Record<string, any> = {};
432	    const dailyMap: Record<
433	      string,
434	      { date: string; entrada: number; saida: number }
435	    > = {};
436	    const categoryMap: Record<string, number> = {};
437	    const hourlyMap: Record<string, number> = {};
438	    const userMap: Record<string, number> = {};
439	
440	    let totalEntrada = 0,
441	      totalSaida = 0,
442	      totalMoves = 0;
443	    let totalEstoqueValor = 0;
444	    let totalEstoqueQtd = 0;
445	
446	    // Base stock value (Using COST price for inventory value) - apenas dos produtos filtrados
447	    // INICIALIZAÇÃO ROBUSTA: Garantir que TODOS os produtos com estoque apareçam na lista, mesmo sem movimento
448	    filteredProducts.forEach((p) => {
449	      totalEstoqueQtd += p.quantidade_atual || 0;
450	      // Use Cost Price if available, otherwise 0 (avoids inflating inventory value with sales price)
451	      const valuationPrice = p.preco_custo || 0;
452	      totalEstoqueValor += (p.quantidade_atual || 0) * valuationPrice;
453	
454	      // Se produto já existe no mapa (por nome duplicado), soma o estoque
455	      if (productStats[p.nome]) {
456	        productStats[p.nome].stock += p.quantidade_atual || 0;
457	      } else {
458	        productStats[p.nome] = {
459	          nome: p.nome,
460	          setor: p.setor,
461	          stock: p.quantidade_atual || 0,
462	          categoria_id: p.categoria_id,
463	          categoria_nome: getCategoriaName(p.categoria_id),
464	          entrada: 0,
465	          saida: 0,
466	          entradaVal: 0,
467	          saidaVal: 0,
468	          moves: 0,
469	          lastMove: null, // Sem movimento no período
470	        };
471	      }
472	    });
473	
474	    movements.forEach((m) => {
475	      const prod = prodMap.get(m.produto_nome);
476	      if (!prod) return; // Produto não está nos filtrados
477	
478	      const price = prod.preco_custo || 0;
479	      const val = viewMode === 'volume' ? m.quantidade : m.quantidade * price;
480	      const rawVal = m.quantidade; // Always volume for internal counts
481	
482	      // Se por acaso o produto não estava no filteredProducts (ex: deletado mas tem histórico), cria entry
483	      if (!productStats[m.produto_nome]) {
484	        productStats[m.produto_nome] = {
485	          nome: m.produto_nome,
486	          setor: prod.setor,
487	          stock: prod.quantidade_atual || 0,
488	          categoria_id: prod.categoria_id,
489	          categoria_nome: getCategoriaName(prod.categoria_id),
490	          entrada: 0,
491	          saida: 0,
492	          entradaVal: 0,
493	          saidaVal: 0,
494	          moves: 0,
495	          lastMove: m.data_movimentacao,
496	        };
497	      }
498	      const ps = productStats[m.produto_nome];
499	      ps.moves++;
500	      totalMoves++;
501	      // Atualiza data do último movimento se for mais recente
502	      if (
503	        !ps.lastMove ||
504	        new Date(m.data_movimentacao) > new Date(ps.lastMove)
505	      ) {
506	        ps.lastMove = m.data_movimentacao;
507	      }
508	
509	      if (m.tipo_movimentacao === 'entrada') {
510	        ps.entrada += rawVal;
511	        ps.entradaVal += rawVal * price;
512	        totalEntrada += val;
513	      } else {
514	        ps.saida += rawVal;
515	        ps.saidaVal += rawVal * price;
516	        totalSaida += val;
517	      }
518	
519	      // Daily
520	      const dayKey = format(parseISO(m.data_movimentacao), 'yyyy-MM-dd');
521	      if (!dailyMap[dayKey])
522	        dailyMap[dayKey] = { date: dayKey, entrada: 0, saida: 0 };
523	      if (m.tipo_movimentacao === 'entrada') dailyMap[dayKey].entrada += val;
524	      else dailyMap[dayKey].saida += val;
525	
526	      // Hourly
527	      const hour = getHours(parseISO(m.data_movimentacao));
528	      const hourKey = `${hour}h`;
529	      hourlyMap[hourKey] = (hourlyMap[hourKey] || 0) + val;
530	
531	      // User
532	      const user = m.usuario_nome || 'Sistema';
533	      userMap[user] = (userMap[user] || 0) + val;
534	
535	      // Category
536	      const cat = m.categoria_nome || getCategoriaName(prod.categoria_id);
537	      categoryMap[cat] = (categoryMap[cat] || 0) + val;
538	    });
539	
540	    const productList = Object.values(productStats);
541	
542	    // Advanced KPIs
543	    const periodDays =
544	      dateRange?.from && dateRange?.to
545	        ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1)
546	        : 30;
547	
548	    // Stockout (Ruptura): Products with 0 stock but were active (had moves) or are listed
549	    // We consider 'Ruptura' products with 0 stock.
550	    const stockoutProducts = filteredProducts.filter(
551	      (p) => !p.quantidade_atual || p.quantidade_atual <= 0,
552	    );
553	    const ruptureRate = filteredProducts.length
554	      ? (stockoutProducts.length / filteredProducts.length) * 100
555	      : 0;
556	
557	    // Dead Stock (Sem Giro): Products with stock > 0 but NO output moves in period
558	    const activeProductNames = new Set(
559	      matchMoves(movements, 'saida').map((m) => m.produto_nome),
560	    );
561	    const deadStockProducts = filteredProducts.filter(
562	      (p) => (p.quantidade_atual || 0) > 0 && !activeProductNames.has(p.nome),
563	    );
564	
565	    // Rankings
566	    const topSaida = [...productList]
567	      .sort((a: any, b: any) =>
568	        viewMode === 'volume' ? b.saida - a.saida : b.saidaVal - a.saidaVal,
569	      )
570	      .slice(0, 10);
571	    const topEntrada = [...productList]
572	      .sort((a: any, b: any) =>
573	        viewMode === 'volume'
574	          ? b.entrada - a.entrada
575	          : b.entradaVal - a.entradaVal,
576	      )
577	      .slice(0, 10);
578	    const lowPerformers = [...productList]
579	      .filter((p: any) => p.saida === 0 && p.stock > 0)
580	      .sort((a: any, b: any) => b.stock - a.stock)
581	      .slice(0, 10);
582	
583	    // Chart Data Structs
584	    const dailyData = Object.values(dailyMap).sort((a, b) =>
585	      a.date.localeCompare(b.date),
586	    );
587	    const categoryData = Object.entries(categoryMap)
588	      .map(([name, value]) => ({ name, value }))
589	      .sort((a, b) => b.value - a.value)
590	      .slice(0, 6);
591	
592	    const hourlyData = Array.from({ length: 24 }, (_, i) => {
593	      const key = `${i}h`;
594	      return { hour: key, value: hourlyMap[key] || 0 };
595	    });
596	
597	    const userData = Object.entries(userMap)
598	      .map(([name, value]) => ({ name, value }))
599	      .sort((a, b) => b.value - a.value)
600	      .slice(0, 10);
601	
602	    const avgDailySaida = totalSaida / periodDays;
603	
