} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import {
  format,
  subDays,
  startOfMonth,
  endOfDay,
  startOfDay,
  parseISO,
  isEqual,
  differenceInDays,
  startOfYear,
  getHours,
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { cn } from '@/shared/lib/utils';
import * as XLSX from 'xlsx';
import { toast as sonnerToast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/shared/ui/table';
import { StoreSelector } from '@/shared/ui/DashboardStoreSelector';

// --- Design System Colors ---
const KPICOLORS = {
  green: 'from-[#57715B] to-[#4A614E] text-white',
  gold: 'from-[#C5A065] to-[#B08D55] text-white',
  red: 'from-[#ef4444] to-[#b91c1c] text-white',
  orange: 'from-[#f97316] to-[#c2410c] text-white',
  dark: 'from-[#2D362E] to-[#1A1A1A] text-[#E6DCCF]',
  blue: 'from-[#3b82f6] to-[#1d4ed8] text-white',
  purple: 'from-[#8b5cf6] to-[#6d28d9] text-white',
  teal: 'from-[#0d9488] to-[#0f766e] text-white',
  emerald: 'from-[#10b981] to-[#059669] text-white',
  rose: 'from-[#f43f5e] to-[#be123c] text-white',
};

const CHART_COLORS = [
  '#C5A065',
  '#57715B',
  '#8B4513',
  '#2D362E',
  '#ef4444',
  '#3b82f6',
  '#8b5cf6',
];

interface AnalyticsMovement {
  movimentacao_id: number;
  tipo_movimentacao: string;
  produto_nome: string;
  categoria_nome: string;
  quantidade: number;
  data_movimentacao: string;
  usuario_nome?: string;
}

interface ProductInfo {
  id: number;
  nome: string;
  preco_custo?: number;
  setor: string;
  categoria_id?: number;
  quantidade_atual?: number;
}

// --- KPI Card Component (Premium Style from LossAnalytics) ---
const KPICard = ({
  title,
  value,
  icon: Icon,
  colorClass,
  subtext,
  onClick,
  trend,
  tooltipText,
}: any) => (
  <div
    onClick={onClick}
    className={cn(
      'rounded-2xl bg-gradient-to-br p-5 shadow-lg relative overflow-hidden group min-h-[140px] flex flex-col justify-between transition-all duration-300',
      colorClass,
      onClick ? 'cursor-pointer hover:scale-[1.02] hover:shadow-xl' : '',
    )}
  >
    <div className="absolute right-[-15px] top-[-15px] opacity-10 rotate-12 group-hover:rotate-0 transition-transform duration-500 scale-150">
      <Icon className="h-24 w-24" />
    </div>
    <div className="relative z-10">
      <div className="flex justify-between items-start mb-2">
        <span className="text-[11px] font-black uppercase tracking-[0.2em] opacity-70 flex items-center gap-1.5">
          {title}
          {tooltipText && (
            <Tooltip>
              <TooltipTrigger asChild>
                <Info className="w-3 h-3 opacity-50 hover:opacity-100 cursor-help" />
              </TooltipTrigger>
              <TooltipContent className="max-w-[200px] text-xs z-50">
                <p>{tooltipText}</p>
              </TooltipContent>
            </Tooltip>
          )}
          {onClick && (
            <ChevronRight className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
          )}
        </span>
        <div className="p-2 bg-white/10 rounded-full backdrop-blur-sm">
          <Icon className="h-4 w-4" />
        </div>
      </div>
      <h2 className="text-3xl font-bold leading-none tracking-tight break-words mb-1 filter drop-shadow-sm">
        {value}
      </h2>
      {(subtext || trend !== undefined) && (
        <div className="flex items-center gap-2 mt-2">
          {trend !== undefined && (
            <Badge
              variant="outline"
              className={cn(
                'bg-white/20 border-none text-white text-[10px] font-bold px-1.5 py-0.5 h-auto',
                trend > 0
                  ? 'bg-green-500/30'
                  : trend < 0
                    ? 'bg-red-500/30'
                    : 'bg-white/10',
              )}
            >
              {trend > 0 ? (
                <TrendingUp className="w-3 h-3 mr-1" />
              ) : trend < 0 ? (
                <TrendingDown className="w-3 h-3 mr-1" />
              ) : null}
              {trend !== 0 ? `${Math.abs(trend).toFixed(1)}%` : '—'}
            </Badge>
          )}
          {subtext && (
            <p className="text-[11px] font-medium opacity-80">{subtext}</p>
          )}
        </div>
      )}
    </div>
  </div>
);

// --- Chart Card Component ---
const ChartCard = ({
  title,
  children,
  className = '',
}: {
  title: string;
  children: React.ReactNode;
  className?: string;
}) => (
  <div
    className={cn(
      'rounded-2xl bg-white/80 dark:bg-[#1A1A1A]/80 backdrop-blur-xl border border-[#57715B]/10 p-5 shadow-sm flex flex-col',
      className,
    )}
  >
    <h3 className="text-xs font-bold text-[#57715B] uppercase tracking-wider mb-4">
      {title}
    </h3>
    <div className="flex-1 w-full min-h-0">{children}</div>
  </div>
);

export default function ProductAnalytics() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const isMobile = useIsMobile();
  const { stores, setSelectedStore } = useStore();
  const { hasData, applyStoreFilter, storeId, selectedStore } =
    useStoreFilter();
  const today = new Date();

  const [dateRange, setDateRange] = useState<DateRange | undefined>({
    from: startOfMonth(today),
    to: today,
  });
  const [viewMode, setViewMode] = useState<'volume' | 'money'>('volume');
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [movements, setMovements] = useState<AnalyticsMovement[]>([]);
  const [products, setProducts] = useState<ProductInfo[]>([]);
  const [isLeaving, setIsLeaving] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<string | null>(null);

  // Filtros de granularidade: Setor e Categoria
  const [selectedSetor, setSelectedSetor] = useState<string>('all');
  const [selectedCategoria, setSelectedCategoria] = useState<string>('all');
  const [setores, setSetores] = useState<string[]>([]);
  const [categorias, setCategorias] = useState<{ id: number; nome: string }[]>(
    [],
  );

  // Fetch Setores e Categorias
  useEffect(() => {
    const loadFilters = async () => {
      try {
        // Buscar setores ativos
        const { data: setoresData } = await supabase
          .from('setores')
          .select('nome')
          .eq('ativo', true)
          .order('nome');

        const setoresList = (setoresData || [])
          .map((s: any) => s.nome)
          .filter((nome: string) => nome && nome.trim() !== '');
        setSetores(setoresList);

        // Buscar categorias
        const { data: categoriasData } = await supabase
          .from('categorias')
          .select('id, nome')
          .order('nome');

        setCategorias(categoriasData || []);
      } catch (error) {
        handleError(error, { domain: 'produtos', operation: 'loadFilters', showToast: false });
      }
    };
    loadFilters();
  }, []);

  // Fetch Data
  useEffect(() => {
    const loadData = async () => {
      if (!hasData) return;
      setIsLoading(true);
      try {
        // Use standardized view that joins products and stock
        const prodQuery = (supabase as any)
          .from('vw_produtos_estoque_lojas')
          .select(
            'id, nome, preco_custo, setor, categoria_id, quantidade_atual',
          )
          .eq('loja_id', storeId); // Filter by store explicitly as view has loja_id

        // prodQuery = applyStoreFilter(prodQuery); // Already filtered by storeId above

        const { data: viewData, error: viewError } = await prodQuery;
        if (viewError) throw viewError;

        const productsWithStock = (viewData || []).map((p: any) => ({
          id: p.id,
          nome: p.nome,
          preco_custo: p.preco_custo,
          setor: p.setor,
          categoria_id: p.categoria_id,
          quantidade_atual: p.quantidade_atual,
        }));
        setProducts(productsWithStock);

        const start = dateRange?.from
          ? startOfDay(dateRange.from)
          : startOfDay(subDays(today, 30));
        const end = dateRange?.to ? endOfDay(dateRange.to) : endOfDay(today);

        // Fetch all movements using pagination to bypass Supabase 1000 row limit
        const PAGE_SIZE = 1000;
        let allMovements: any[] = [];
        let page = 0;
        let hasMore = true;

        while (hasMore) {
          const from = page * PAGE_SIZE;
          const to = from + PAGE_SIZE - 1;

          const { data: movData, error: movError } = await supabase
            .from('movimentacoes')
            .select(
              `
                            id,
                            tipo_movimentacao,
                            quantidade,
                            data_movimentacao,
                            loja_id,
                            produto:produtos_master!inner(nome, categoria:categorias(nome)),
                            usuario:usuarios(nome)
                        `,
            )
            .eq('loja_id', storeId)
            .gte('data_movimentacao', start.toISOString())
            .lte('data_movimentacao', end.toISOString())
            .order('data_movimentacao', { ascending: false })
            .range(from, to);

          if (movError) throw movError;

          if (movData && movData.length > 0) {
            allMovements = [...allMovements, ...movData];
            page++;
            hasMore = movData.length === PAGE_SIZE;
          } else {
            hasMore = false;
          }

          if (page >= 50) hasMore = false; // Safety limit
        }

        // Transform to expected format
        const transformedMovements: AnalyticsMovement[] = allMovements.map(
          (m: any) => ({
            movimentacao_id: m.id,
            tipo_movimentacao: m.tipo_movimentacao,
            produto_nome: m.produto?.nome || 'Desconhecido',
            categoria_nome: m.produto?.categoria?.nome || 'Outros',
            quantidade: m.quantidade,
            data_movimentacao: m.data_movimentacao,
            usuario_nome: m.usuario?.nome || 'Sistema',
          }),
        );
        setMovements(transformedMovements);
      } catch (error) {
        handleError(error, { domain: 'produtos', operation: 'loadAnalytics', showToast: false });
        toast({
          title: 'Erro ao carregar dados',
          description:
            (error as any)?.message ||
            'Verifique o console para mais detalhes.',
          variant: 'destructive',
        });
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasData, storeId, dateRange]);

  // Analytics computations
  const analytics = useMemo(() => {
    // Filtrar produtos por setor e categoria selecionados
    const filteredProducts = products.filter((p) => {
      const matchSetor = selectedSetor === 'all' || p.setor === selectedSetor;
      const matchCategoria =
        selectedCategoria === 'all' ||
        p.categoria_id?.toString() === selectedCategoria;
      return matchSetor && matchCategoria;
    });

    const prodMap = new Map<string, ProductInfo>();
    filteredProducts.forEach((p) => prodMap.set(p.nome, p));

    // Mapear categoria_id para nome
    const getCategoriaName = (catId?: number) => {
      if (!catId) return 'Outros';
      const cat = categorias.find((c) => c.id === catId);
      return cat?.nome || 'Outros';
    };

    const productStats: Record<string, any> = {};
    const dailyMap: Record<
      string,
      { date: string; entrada: number; saida: number }
    > = {};
    const categoryMap: Record<string, number> = {};
    const hourlyMap: Record<string, number> = {};
    const userMap: Record<string, number> = {};

    let totalEntrada = 0,
      totalSaida = 0,
      totalMoves = 0;
    let totalEstoqueValor = 0;
    let totalEstoqueQtd = 0;

    // Base stock value (Using COST price for inventory value) - apenas dos produtos filtrados
    // INICIALIZAÇÃO ROBUSTA: Garantir que TODOS os produtos com estoque apareçam na lista, mesmo sem movimento
    filteredProducts.forEach((p) => {
      totalEstoqueQtd += p.quantidade_atual || 0;
      // Use Cost Price if available, otherwise 0 (avoids inflating inventory value with sales price)
      const valuationPrice = p.preco_custo || 0;
      totalEstoqueValor += (p.quantidade_atual || 0) * valuationPrice;

      // Se produto já existe no mapa (por nome duplicado), soma o estoque
      if (productStats[p.nome]) {
        productStats[p.nome].stock += p.quantidade_atual || 0;
      } else {
        productStats[p.nome] = {
          nome: p.nome,
          setor: p.setor,
          stock: p.quantidade_atual || 0,
          categoria_id: p.categoria_id,
          categoria_nome: getCategoriaName(p.categoria_id),
          entrada: 0,
          saida: 0,
          entradaVal: 0,
          saidaVal: 0,
          moves: 0,
          lastMove: null, // Sem movimento no período
        };
      }
    });

    movements.forEach((m) => {
      const prod = prodMap.get(m.produto_nome);
      if (!prod) return; // Produto não está nos filtrados

      const price = prod.preco_custo || 0;
      const val = viewMode === 'volume' ? m.quantidade : m.quantidade * price;
      const rawVal = m.quantidade; // Always volume for internal counts

      // Se por acaso o produto não estava no filteredProducts (ex: deletado mas tem histórico), cria entry
      if (!productStats[m.produto_nome]) {
        productStats[m.produto_nome] = {
          nome: m.produto_nome,
          setor: prod.setor,
          stock: prod.quantidade_atual || 0,
          categoria_id: prod.categoria_id,
          categoria_nome: getCategoriaName(prod.categoria_id),
          entrada: 0,
          saida: 0,
          entradaVal: 0,
          saidaVal: 0,
          moves: 0,
          lastMove: m.data_movimentacao,
        };
      }
      const ps = productStats[m.produto_nome];
      ps.moves++;
      totalMoves++;
      // Atualiza data do último movimento se for mais recente
      if (
        !ps.lastMove ||
        new Date(m.data_movimentacao) > new Date(ps.lastMove)
      ) {
        ps.lastMove = m.data_movimentacao;
      }

      if (m.tipo_movimentacao === 'entrada') {
        ps.entrada += rawVal;
        ps.entradaVal += rawVal * price;
        totalEntrada += val;
      } else {
        ps.saida += rawVal;
        ps.saidaVal += rawVal * price;
        totalSaida += val;
      }

      // Daily
      const dayKey = format(parseISO(m.data_movimentacao), 'yyyy-MM-dd');
      if (!dailyMap[dayKey])
        dailyMap[dayKey] = { date: dayKey, entrada: 0, saida: 0 };
      if (m.tipo_movimentacao === 'entrada') dailyMap[dayKey].entrada += val;
      else dailyMap[dayKey].saida += val;

      // Hourly
      const hour = getHours(parseISO(m.data_movimentacao));
      const hourKey = `${hour}h`;
      hourlyMap[hourKey] = (hourlyMap[hourKey] || 0) + val;

      // User
      const user = m.usuario_nome || 'Sistema';
      userMap[user] = (userMap[user] || 0) + val;

      // Category
      const cat = m.categoria_nome || getCategoriaName(prod.categoria_id);
      categoryMap[cat] = (categoryMap[cat] || 0) + val;
    });

    const productList = Object.values(productStats);

    // Advanced KPIs
    const periodDays =
      dateRange?.from && dateRange?.to
        ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1)
        : 30;

    // Stockout (Ruptura): Products with 0 stock but were active (had moves) or are listed
    // We consider 'Ruptura' products with 0 stock.
    const stockoutProducts = filteredProducts.filter(
      (p) => !p.quantidade_atual || p.quantidade_atual <= 0,
    );
    const ruptureRate = filteredProducts.length
      ? (stockoutProducts.length / filteredProducts.length) * 100
      : 0;

    // Dead Stock (Sem Giro): Products with stock > 0 but NO output moves in period
    const activeProductNames = new Set(
      matchMoves(movements, 'saida').map((m) => m.produto_nome),
    );
    const deadStockProducts = filteredProducts.filter(
      (p) => (p.quantidade_atual || 0) > 0 && !activeProductNames.has(p.nome),
    );

    // Rankings
    const topSaida = [...productList]
      .sort((a: any, b: any) =>
        viewMode === 'volume' ? b.saida - a.saida : b.saidaVal - a.saidaVal,
      )
      .slice(0, 10);
    const topEntrada = [...productList]
      .sort((a: any, b: any) =>
        viewMode === 'volume'
          ? b.entrada - a.entrada
          : b.entradaVal - a.entradaVal,
      )
      .slice(0, 10);
    const lowPerformers = [...productList]
      .filter((p: any) => p.saida === 0 && p.stock > 0)
      .sort((a: any, b: any) => b.stock - a.stock)
      .slice(0, 10);

    // Chart Data Structs
    const dailyData = Object.values(dailyMap).sort((a, b) =>
      a.date.localeCompare(b.date),
    );
    const categoryData = Object.entries(categoryMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 6);

    const hourlyData = Array.from({ length: 24 }, (_, i) => {
      const key = `${i}h`;
      return { hour: key, value: hourlyMap[key] || 0 };
    });

    const userData = Object.entries(userMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 10);

    const avgDailySaida = totalSaida / periodDays;

    // Coverage (Days on Hand) = Current Stock / Avg Daily Sales
    // If Avg Daily Sales is 0, coverage is Infinite (or 0 for safety)
    const coverageDays =
      avgDailySaida > 0
        ? (viewMode === 'volume' ? totalEstoqueQtd : totalEstoqueValor) /
          avgDailySaida
        : 0;

    return {
      totalEntrada,
      totalSaida,
      totalMoves,
      avgDailySaida,
      periodDays,
      productList,
      topSaida,
      topEntrada,
      lowPerformers,
      dailyData,
      categoryData,
      hourlyData,
      userData,
      ruptureRate,
      deadStockCount: deadStockProducts.length,
      coverageDays,
      totalEstoqueQtd,
      totalEstoqueValor,
      stockoutCount: stockoutProducts.length,
      filteredProductsCount: filteredProducts.length,
    };
  }, [
    movements,
    products,
    viewMode,
    dateRange,
    selectedSetor,
    selectedCategoria,
    categorias,
  ]);

  const formatValue = (val: number) =>
    viewMode === 'volume'
      ? val.toLocaleString('pt-BR')
      : new Intl.NumberFormat('pt-BR', {
          style: 'currency',
          currency: 'BRL',
        }).format(val);

  const isRangeActive = (start: Date, end: Date) => {
    if (!dateRange?.from || !dateRange?.to) return false;
    return (
      isEqual(startOfDay(start), startOfDay(dateRange.from)) &&
      isEqual(startOfDay(end), startOfDay(dateRange.to))
    );
  };

  const handleExport = () => {
    if (!analytics.productList.length) {
      sonnerToast.error('Sem dados para exportar.');
      return;
    }
    const header = [
      'Produto',
      'Setor',
      'Entradas (Qtd)',
      'Saídas (Qtd)',
      'Estoque Atual',
      'Movimentações',
      'Ultima Movimentação',
    ];
    const rows = analytics.productList.map((p: any) => [
      p.nome,
      p.setor,
      p.entrada,
      p.saida,
      p.stock,
      p.moves,
      p.lastMove ? format(parseISO(p.lastMove), 'dd/MM/yyyy') : '-',
    ]);
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet([header, ...rows]);
    XLSX.utils.book_append_sheet(wb, ws, 'Produtos');
    XLSX.writeFile(
      wb,
      `Analytics_Produtos_${format(new Date(), 'yyyyMMdd')}.xlsx`,
    );
    sonnerToast.success('Relatório exportado!');
  };

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return analytics.productList;
    return analytics.productList.filter((p: any) =>
      p.nome.toLowerCase().includes(searchTerm.toLowerCase()),
    );
  }, [analytics.productList, searchTerm]);

  return (
    <div className="flex flex-col h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-hidden relative font-sans">
      {/* Awning */}
      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />

      {/* Background */}
      <div
        className="fixed top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] pointer-events-none animate-pulse"
        style={{ animationDuration: '10s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
      </div>
      <div
        className="fixed bottom-[-10%] left-[-15%] w-[400px] h-[400px] opacity-[0.03] pointer-events-none animate-pulse"
        style={{ animationDuration: '12s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
      </div>
      <div className="fixed top-[20%] left-[10%] w-[200px] h-[200px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
      <div className="fixed bottom-[30%] right-[10%] w-[250px] h-[250px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />

      {/* Header - Style from VerificacaoPerdas */}
      <div className="relative z-20 px-6 pt-8 pb-4 flex flex-col md:flex-row items-center justify-between gap-4 flex-shrink-0">
        <div className="flex items-center gap-4 w-full md:w-auto">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => {
              setIsLeaving(true);
              setTimeout(() => navigate('/produtos'), 180);
            }}
            className="rounded-full bg-white/50 dark:bg-white/10 hover:bg-white/80 dark:hover:bg-white/20 backdrop-blur-sm shadow-sm"
          >
            <ArrowLeft className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
          </Button>
          <div>
            <h1 className="text-xl font-bold text-[#2D362E] dark:text-white flex items-center gap-2">
              Analytics de Produtos
            </h1>
            <p className="text-xs text-muted-foreground font-medium ml-1">
              Inteligência de Estoque & Movimentações
            </p>
          </div>
        </div>

        {/* Store Selector on Header */}
        <div className="w-full md:w-auto">
          <StoreSelector />
        </div>
      </div>

      <div
        className={cn(
          'flex-1 overflow-y-auto min-h-0 pb-24 transition-all duration-300',
          isLeaving ? 'opacity-0 translate-x-4' : 'opacity-100',
        )}
      >
        <div className="px-6 space-y-6">
          {/* Filter Header - Style from LossAnalytics */}
          <div className="flex flex-col gap-4 bg-white/50 dark:bg-black/20 p-3 rounded-2xl backdrop-blur-sm border border-[#57715B]/10">
            {/* Linha 1: Data, Export e período rápido */}
            <div className="flex flex-col md:flex-row items-center justify-between gap-4">
              <div className="flex items-center gap-2 w-full md:w-auto">
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        'w-full md:w-[260px] justify-start text-left font-normal bg-white/50 border-[#57715B]/10 h-10 rounded-xl',
                        !dateRange && 'text-muted-foreground',
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4 text-[#57715B]" />
                      {dateRange?.from ? (
                        <span className="truncate text-xs">
                          {format(dateRange.from, 'dd/MM/yyyy')} -{' '}
                          {format(dateRange.to || dateRange.from, 'dd/MM/yyyy')}
                        </span>
                      ) : (
                        <span>Selecione um período</span>
                      )}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent
                    className="w-auto p-0 border-[#57715B]/10 rounded-xl shadow-xl"
                    align="start"
                  >
                    <Calendar
                      initialFocus
                      mode="range"
                      selected={dateRange}
                      onSelect={setDateRange}
                      numberOfMonths={1}
                      locale={ptBR}
                      className="p-3"
                    />
                  </PopoverContent>
                </Popover>
                <Button data-mia-action="export"
            data-mia-expects-toast="export"
                  onClick={handleExport}
                  variant="ghost"
                  size="icon"
                  className="text-[#57715B] hover:bg-[#57715B]/10 rounded-xl h-10 w-10"
                  title="Exportar Excel"
                >
                  <Download className="w-5 h-5" />
                </Button>
              </div>

              {/* Volume/R$ Toggle - Style from SalesAnalytics */}
              <div className="bg-gray-100/50 dark:bg-white/5 p-1 rounded-xl flex items-center">
                <button
                  onClick={() => setViewMode('volume')}
                  className={cn(
                    'px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all',
                    viewMode === 'volume'
                      ? 'bg-white shadow text-[#57715B]'
                      : 'text-gray-400 hover:text-gray-600',
                  )}
                >
                  Volume
                </button>
                <button
                  onClick={() => setViewMode('money')}
                  className={cn(
                    'px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all',
                    viewMode === 'money'
                      ? 'bg-white shadow text-[#57715B]'
                      : 'text-gray-400 hover:text-gray-600',
                  )}
                >
                  R$
                </button>
              </div>

              <div className="flex gap-1 overflow-x-auto w-full md:w-auto pb-1 md:pb-0 scrollbar-hide">
                {[
                  { label: '7 Dias', start: subDays(today, 7), end: today },
                  { label: '30 Dias', start: subDays(today, 30), end: today },
                  { label: 'Este Mês', start: startOfMonth(today), end: today },
                  { label: 'Este Ano', start: startOfYear(today), end: today },
                ].map((opt) => (
                  <Button
                    key={opt.label}
                    variant={
                      isRangeActive(opt.start, opt.end) ? 'default' : 'ghost'
                    }
                    size="sm"
                    onClick={() =>
                      setDateRange({ from: opt.start, to: opt.end })
                    }
                    className={cn(
                      'rounded-xl text-[10px] md:text-xs',
                      isRangeActive(opt.start, opt.end) &&
                        'bg-[#57715B] text-white',
                    )}
                  >
                    {opt.label}
                  </Button>
                ))}
              </div>
            </div>

            {/* Linha 2: Filtros de Setor e Categoria para granularidade */}
            <div className="flex flex-col sm:flex-row items-center gap-3 border-t border-[#57715B]/10 pt-3">
              <div className="flex items-center gap-2 text-[#57715B]">
                <Filter className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-wider">
                  Granularidade:
                </span>
              </div>

              {/* Setor Selector */}
              <Select value={selectedSetor} onValueChange={setSelectedSetor}>
                <SelectTrigger data-mia-filter="selected_setor" className="w-full sm:w-[180px] h-9 bg-white/50 border-[#57715B]/10 rounded-xl text-xs">
                  <SelectValue placeholder="Todos os Setores" />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-[#57715B]/10">
                  <SelectItem value="all" className="text-xs">
                    Todos os Setores
                  </SelectItem>
                  {setores.map((setor) => (
                    <SelectItem key={setor} value={setor} className="text-xs">
                      {setor}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {/* Categoria Selector */}
              <Select
                value={selectedCategoria}
                onValueChange={setSelectedCategoria}
              >
                <SelectTrigger data-mia-filter="selected_categoria" className="w-full sm:w-[200px] h-9 bg-white/50 border-[#57715B]/10 rounded-xl text-xs">
                  <SelectValue placeholder="Todas as Categorias" />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-[#57715B]/10 max-h-[300px]">
                  <SelectItem value="all" className="text-xs">
                    Todas as Categorias
                  </SelectItem>
                  {categorias.map((cat) => (
                    <SelectItem
                      key={cat.id}
                      value={cat.id.toString()}
                      className="text-xs"
                    >
                      {cat.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {/* Indicador de filtros ativos */}
              {(selectedSetor !== 'all' || selectedCategoria !== 'all') && (
                <div className="flex items-center gap-2">
                  <Badge
                    variant="secondary"
                    className="bg-[#57715B]/10 text-[#57715B] text-[10px] h-6"
                  >
                    {analytics.filteredProductsCount} produtos
                  </Badge>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      setSelectedSetor('all');
                      setSelectedCategoria('all');
                    }}
                    className="h-6 px-2 text-[10px] text-muted-foreground hover:text-[#57715B]"
                  >
                    Limpar filtros
                  </Button>
                </div>
              )}
            </div>
          </div>

          {/* KPI Grid Row 1 (Core) */}
          <TooltipProvider delayDuration={300}>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
              <KPICard
                title="Total Entradas"
                value={formatValue(analytics.totalEntrada)}
                icon={ArrowDownToLine}
                colorClass={KPICOLORS.green}
                subtext={`${analytics.periodDays} dias`}
                tooltipText="Valor total de entradas registradas APENAS neste período selecionado."
              />
              <KPICard
                title="Total Saídas"
                value={formatValue(analytics.totalSaida)}
                icon={ArrowUpFromLine}
                colorClass={KPICOLORS.red}
                subtext="Consumo no período"
                tooltipText="Valor total de saídas registradas APENAS neste período selecionado."
              />
              <KPICard
                title="Operações Ent/Sai"
                value={analytics.totalMoves.toLocaleString('pt-BR')}
                icon={Activity}
                colorClass={KPICOLORS.dark}
                subtext="Volume Movimentado"
                tooltipText="Quantidade de registros de movimentação no período."
              />
              <KPICard
                title="Estoque Atual"
                value={formatValue(
                  viewMode === 'volume'
                    ? analytics.totalEstoqueQtd
                    : analytics.totalEstoqueValor,
                )}
                icon={Package}
                colorClass={KPICOLORS.gold}
                subtext="Posição Atual"
                tooltipText="Valor TOTAL acumulado do estoque hoje (Snapshot). Inclui itens parados sem movimentação recente."
              />
            </div>
          </TooltipProvider>

          {/* KPI Grid Row 2 (Advanced) */}
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
            <KPICard
              title="Produtos Sem Giro"
              value={analytics.deadStockCount}
              icon={Layers}
              colorClass={KPICOLORS.dark}
              subtext="Com estoque e sem saída"
            />
            <KPICard
              title="Ticket Médio Saída"
              value={formatValue(
                analytics.totalMoves > 0
                  ? analytics.totalSaida / analytics.totalMoves
                  : 0,
              )}
              icon={Wallet}
              colorClass={KPICOLORS.teal}
              subtext="Por movimentação"
            />
          </div>

          {/* Charts Row 1 */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <ChartCard title="Evolução Diária" className="lg:col-span-2 h-80">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={analytics.dailyData}>
                  <defs>
                    <linearGradient id="colorEnt" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#57715B" stopOpacity={0.4} />
                      <stop offset="95%" stopColor="#57715B" stopOpacity={0} />
                    </linearGradient>
                    <linearGradient id="colorSai" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#ef4444" stopOpacity={0.4} />
                      <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid
                    strokeDasharray="3 3"
                    vertical={false}
                    stroke="rgba(0,0,0,0.05)"
                  />
                  <XAxis
                    dataKey="date"
                    tickFormatter={(v) => format(parseISO(v), 'dd/MM')}
                    axisLine={false}
                    tickLine={false}
                    tick={{ fill: '#57715B', fontSize: 10 }}
                  />
                  <YAxis
                    axisLine={false}
                    tickLine={false}
                    tick={{ fill: '#57715B', fontSize: 10 }}
                  />
                  <RechartsTooltip
                    contentStyle={{
                      borderRadius: '12px',
                      border: 'none',
                      boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                    }}
                    formatter={(v: number) => formatValue(v)}
                  />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="entrada"
                    name="Entradas"
                    stroke="#57715B"
                    fillOpacity={1}
                    fill="url(#colorEnt)"
                    strokeWidth={2}
                  />
                  <Area
                    type="monotone"
                    dataKey="saida"
                    name="Saídas"
                    stroke="#ef4444"
                    fillOpacity={1}
                    fill="url(#colorSai)"
                    strokeWidth={2}
                  />
                </AreaChart>
