1	import { useQuery } from '@tanstack/react-query';
2	import { supabase } from '@/integrations/supabase/client';
3	
4	export interface StoreSales {
5	  loja_id: number;
6	  loja_nome: string;
7	  vendas_ontem: number;
8	  media_diaria: number;
9	}
10	
11	export interface ForecastItem {
12	  produto_master_id: number;
13	  nome: string;
14	  setor: string;
15	  demanda_diaria_media: number; // média diária (soma de todas lojas)
16	  demanda_diaria_total: number;
17	  fator_dia: number;
18	  vendas_ontem_total: number;
