23	  dias_dados: number;
24	  // ABC
25	  faturamento_60d: number;
26	  curva: 'A' | 'B' | 'C';
27	  pct_faturamento: number; // % acumulado do faturamento total
28	}
29	
30	export interface AbcItem {
31	  produto_master_id: number;
32	  nome: string;
33	  faturamento: number;
34	  pct: number;
35	  curva: 'A' | 'B' | 'C';
36	}
37	
38	export interface ForecastAssessment {
39	  totalProdutos: number;
40	  criticos: number;       // < 1 dia de cobertura
41	  baixos: number;         // 1-2 dias
42	  ok: number;             // 2-4 dias
43	  cobertos: number;       // 4+ dias
44	  demandaTotalOntem: number;
45	  topCriticos: string[];  // nomes dos 3 mais urgentes
46	  topVendidos: string[];  // nomes dos 3 mais vendidos ontem
47	}
48	
49	const DOW_NAMES = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
50	const LOJA_NAMES: Record<number, string> = {
51	  1: 'Fábrica', 2: 'Asa Sul', 3: 'Asa Norte',
52	  4: 'Lago Sul', 5: 'Águas Claras', 6: 'BSB Shopping',
53	};
54	
55	const DEFAULT_COVERAGE_DAYS = 3; // meta padrão de cobertura
56	
57	export function useProductionForecast(coverageDays = DEFAULT_COVERAGE_DAYS) {
58	  const today = new Date();
59	  const dow = today.getDay();
60	  const dowName = DOW_NAMES[dow];
61	
62	  return useQuery({
63	    queryKey: ['production-forecast', dow, coverageDays],
64	    queryFn: async (): Promise<{
65	      items: ForecastItem[];
66	      abcCurve: AbcItem[];
67	      assessment: ForecastAssessment;
68	      dowName: string;
69	      dataRange: string;
70	      yesterdayDate: string;
71	      coverageDays: number;
72	    }> => {
73	      const sixtyDaysAgo = new Date(today);
74	      sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);
75	      const fromDate = sixtyDaysAgo.toISOString().split('T')[0];
76	      const todayStr = today.toISOString().split('T')[0];
77	
78	      const yesterday = new Date(today);
79	      yesterday.setDate(yesterday.getDate() - 1);
80	      const yesterdayStr = yesterday.toISOString().split('T')[0];
81	
82	      // Força sync dos últimos 3 dias de TODAS as lojas Degust (4, 5, 6)
83	      // Para garantir que demanda recente está atualizada no cache
84	      const DEGUST_LOJA_IDS_SYNC = [4, 5, 6];
85	      const threeDaysAgo = new Date(today);
86	      threeDaysAgo.setDate(threeDaysAgo.getDate() - 3);
87	      const syncStart = threeDaysAgo.toISOString().split('T')[0];
88	
89	      await Promise.all(
90	        DEGUST_LOJA_IDS_SYNC.map(lojaId =>
91	          supabase.functions.invoke('degust-sync-sales', {
92	            body: { startDate: syncStart, endDate: todayStr, lojaId },
93	          }).catch(err => console.warn(`[useProductionForecast] sync loja ${lojaId} falhou:`, err))
94	        )
95	      );
96	
97	      // Fetch paralelo: Degust (3 lojas) + Linx (2 lojas) + Estoque fábrica
98	      // IMPORTANTE: Supabase limita em 1000 rows por default. Precisamos de TODAS.
99	      // Solução: paginar ou usar .limit() grande. Degust tem ~7k rows em 60 dias, Linx ~20k+
100	      async function fetchAll(query: any): Promise<any[]> {
101	        const PAGE_SIZE = 1000;
102	        let allData: any[] = [];
103	        let offset = 0;
104	        while (true) {
105	          const { data, error } = await query.range(offset, offset + PAGE_SIZE - 1);
106	          if (error) throw error;
107	          if (!data || data.length === 0) break;
108	          allData = allData.concat(data);
109	          if (data.length < PAGE_SIZE) break; // última página
110	          offset += PAGE_SIZE;
111	        }
112	        return allData;
113	      }
114	
115	      const [degustData, linxData, stockRes] = await Promise.all([
116	        // Degust: lojas 4, 5, 6
117	        fetchAll(
118	          supabase
119	            .from('degust_vendas_diarias')
120	            .select('produto_master_id, loja_id, data, quantidade, valor_total')
121	            .gte('data', fromDate)
122	            .not('produto_master_id', 'is', null)
123	        ),
124	        // Linx: lojas 2, 3
125	        fetchAll(
126	          supabase
127	            .from('historico_vendas')
128	            .select('produto_master_id, loja_id, data, quantidade, valor_total')
129	            .gte('data', fromDate)
130	            .in('loja_id', [2, 3])
131	            .not('produto_master_id', 'is', null)
132	        ),
133	        // Estoque fábrica
134	        supabase
135	          .from('estoque')
136	          .select('produto_master_id, quantidade_atual')
137	          .eq('loja_id', 1)
138	          .gt('quantidade_atual', 0),
139	      ]);
140	
141	      const degustRes = { data: degustData, error: null };
142	      const linxRes = { data: linxData, error: null };
143	
144	      // Unificar vendas de ambas as fontes
145	      const salesRes = {
146	        data: [...(degustRes.data || []), ...(linxRes.data || [])],
147	        error: degustRes.error || linxRes.error,
148	      };
149	
150	      // Debug: verificar o que cada fonte retorna
151	      const degustCount = degustRes.data?.length ?? 0;
152	      const linxCount = linxRes.data?.length ?? 0;
153	      console.log(`[useProductionForecast] Degust: ${degustCount} rows | Linx: ${linxCount} rows | yesterdayStr: ${yesterdayStr}`);
154	      // Amostra das primeiras 3 rows de cada fonte pra ver formato da data
155	      if (degustRes.data?.[0]) console.log('[useProductionForecast] Degust sample:', JSON.stringify(degustRes.data[0]));
156	      if (linxRes.data?.[0]) console.log('[useProductionForecast] Linx sample:', JSON.stringify(linxRes.data[0]));
157	      // Contar quantas vendas de ontem existem em cada fonte
158	      const degustYesterday = (degustRes.data || []).filter(s => String(s.data).split('T')[0] === yesterdayStr);
159	      const linxYesterday = (linxRes.data || []).filter(s => String(s.data).split('T')[0] === yesterdayStr);
160	      console.log(`[useProductionForecast] Ontem (${yesterdayStr}): Degust=${degustYesterday.length} rows, Linx=${linxYesterday.length} rows`);
161	
162	      if (salesRes.error) throw salesRes.error;
163	      const salesData = salesRes.data || [];
164	      const emptyResult = {
165	        items: [], abcCurve: [], dowName, dataRange: '', yesterdayDate: yesterdayStr, coverageDays,
166	        assessment: { totalProdutos: 0, criticos: 0, baixos: 0, ok: 0, cobertos: 0, demandaTotalOntem: 0, topCriticos: [], topVendidos: [] },
167	      };
168	      if (salesData.length === 0) return emptyResult;
169	
170	      // Produtos ativos
171	      const productIds = [...new Set(salesData.map(s => s.produto_master_id).filter(Boolean))];
172	      const { data: products, error: prodError } = await supabase
173	        .from('produtos_master')
174	        .select('id, nome, setor')
175	        .eq('ativo', true)
176	        .in('setor', ['PRODUTOS', 'CÂMARA FRIA', 'Câmara Fria'])
177	        .in('id', productIds);
178	      if (prodError) throw prodError;
179	      const productMap = new Map(products?.map(p => [p.id, p]) || []);
180	
181	      // Estoque fábrica
182	      const stockMap = new Map<number, number>();
183	      for (const s of stockRes.data || []) {
184	        if (s.produto_master_id) stockMap.set(s.produto_master_id, Number(s.quantidade_atual) || 0);
185	      }
186	
187	      // Passo 1: Agregar por (produto × data) — SOMA cross-lojas
188	      // Isso dá a demanda total da fábrica por produto em cada dia
189	      const productDateTotal = new Map<number, Map<string, number>>(); // pid → date → qty_total_fabrica
190	      const yesterdayByProductLoja = new Map<string, number>();
191	      const productRevenue = new Map<number, number>(); // faturamento 60d
192	      const productQtdTotal = new Map<number, number>(); // quantidade 60d
193	
194	      for (const sale of salesData) {
195	        const pid = sale.produto_master_id;
196	        if (!pid || !productMap.has(pid)) continue;
197	        const qty = Number(sale.quantidade) || 0;
198	
199	        // Acumular faturamento e quantidade totais
200	        productRevenue.set(pid, (productRevenue.get(pid) || 0) + (Number(sale.valor_total) || 0));
201	        productQtdTotal.set(pid, (productQtdTotal.get(pid) || 0) + qty);
202	
203	        // Agregar por data (soma cross-lojas)
204	        const saleDateNorm = String(sale.data).split('T')[0];
205	        if (!productDateTotal.has(pid)) productDateTotal.set(pid, new Map());
206	        const dateMap = productDateTotal.get(pid)!;
207	        dateMap.set(saleDateNorm, (dateMap.get(saleDateNorm) || 0) + qty);
208	
