import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

export interface StoreSales {
  loja_id: number;
  loja_nome: string;
  vendas_ontem: number;
  media_diaria: number;
}

export interface ForecastItem {
  produto_master_id: number;
  nome: string;
  setor: string;
  demanda_diaria_media: number; // média diária (soma de todas lojas)
  demanda_diaria_total: number;
  fator_dia: number;
  vendas_ontem_total: number;
  vendas_por_loja: StoreSales[];
  estoque_fabrica: number;
  cobertura_dias: number;
  sugestao_producao: number;
  dias_dados: number;
  // ABC
  faturamento_60d: number;
  curva: 'A' | 'B' | 'C';
  pct_faturamento: number; // % acumulado do faturamento total
}

export interface AbcItem {
  produto_master_id: number;
  nome: string;
  faturamento: number;
  pct: number;
  curva: 'A' | 'B' | 'C';
}

export interface ForecastAssessment {
  totalProdutos: number;
  criticos: number;       // < 1 dia de cobertura
  baixos: number;         // 1-2 dias
  ok: number;             // 2-4 dias
  cobertos: number;       // 4+ dias
  demandaTotalOntem: number;
  topCriticos: string[];  // nomes dos 3 mais urgentes
  topVendidos: string[];  // nomes dos 3 mais vendidos ontem
}

const DOW_NAMES = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
const LOJA_NAMES: Record<number, string> = {
  1: 'Fábrica', 2: 'Asa Sul', 3: 'Asa Norte',
  4: 'Lago Sul', 5: 'Águas Claras', 6: 'BSB Shopping',
};

const DEFAULT_COVERAGE_DAYS = 3; // meta padrão de cobertura

export function useProductionForecast(coverageDays = DEFAULT_COVERAGE_DAYS) {
  const today = new Date();
  const dow = today.getDay();
  const dowName = DOW_NAMES[dow];

  return useQuery({
    queryKey: ['production-forecast', dow, coverageDays],
    queryFn: async (): Promise<{
      items: ForecastItem[];
      abcCurve: AbcItem[];
      assessment: ForecastAssessment;
      dowName: string;
      dataRange: string;
      yesterdayDate: string;
      coverageDays: number;
    }> => {
      const sixtyDaysAgo = new Date(today);
      sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);
      const fromDate = sixtyDaysAgo.toISOString().split('T')[0];
      const todayStr = today.toISOString().split('T')[0];

      const yesterday = new Date(today);
      yesterday.setDate(yesterday.getDate() - 1);
      const yesterdayStr = yesterday.toISOString().split('T')[0];

      // Força sync dos últimos 3 dias de TODAS as lojas Degust (4, 5, 6)
      // Para garantir que demanda recente está atualizada no cache
      const DEGUST_LOJA_IDS_SYNC = [4, 5, 6];
      const threeDaysAgo = new Date(today);
      threeDaysAgo.setDate(threeDaysAgo.getDate() - 3);
      const syncStart = threeDaysAgo.toISOString().split('T')[0];

      await Promise.all(
        DEGUST_LOJA_IDS_SYNC.map(lojaId =>
          supabase.functions.invoke('degust-sync-sales', {
            body: { startDate: syncStart, endDate: todayStr, lojaId },
          }).catch(err => console.warn(`[useProductionForecast] sync loja ${lojaId} falhou:`, err))
        )
      );

      // Fetch paralelo: Degust (3 lojas) + Linx (2 lojas) + Estoque fábrica
      // IMPORTANTE: Supabase limita em 1000 rows por default. Precisamos de TODAS.
      // Solução: paginar ou usar .limit() grande. Degust tem ~7k rows em 60 dias, Linx ~20k+
      async function fetchAll(query: any): Promise<any[]> {
        const PAGE_SIZE = 1000;
        let allData: any[] = [];
        let offset = 0;
        while (true) {
          const { data, error } = await query.range(offset, offset + PAGE_SIZE - 1);
          if (error) throw error;
          if (!data || data.length === 0) break;
          allData = allData.concat(data);
          if (data.length < PAGE_SIZE) break; // última página
          offset += PAGE_SIZE;
        }
        return allData;
      }

      const [degustData, linxData, stockRes] = await Promise.all([
        // Degust: lojas 4, 5, 6
        fetchAll(
          supabase
            .from('degust_vendas_diarias')
            .select('produto_master_id, loja_id, data, quantidade, valor_total')
            .gte('data', fromDate)
            .not('produto_master_id', 'is', null)
        ),
        // Linx: lojas 2, 3
        fetchAll(
          supabase
            .from('historico_vendas')
            .select('produto_master_id, loja_id, data, quantidade, valor_total')
            .gte('data', fromDate)
            .in('loja_id', [2, 3])
            .not('produto_master_id', 'is', null)
        ),
        // Estoque fábrica
        supabase
          .from('estoque')
          .select('produto_master_id, quantidade_atual')
          .eq('loja_id', 1)
          .gt('quantidade_atual', 0),
      ]);

      const degustRes = { data: degustData, error: null };
      const linxRes = { data: linxData, error: null };

      // Unificar vendas de ambas as fontes
      const salesRes = {
        data: [...(degustRes.data || []), ...(linxRes.data || [])],
        error: degustRes.error || linxRes.error,
      };

      // Debug: verificar o que cada fonte retorna
      const degustCount = degustRes.data?.length ?? 0;
      const linxCount = linxRes.data?.length ?? 0;
      console.log(`[useProductionForecast] Degust: ${degustCount} rows | Linx: ${linxCount} rows | yesterdayStr: ${yesterdayStr}`);
      // Amostra das primeiras 3 rows de cada fonte pra ver formato da data
      if (degustRes.data?.[0]) console.log('[useProductionForecast] Degust sample:', JSON.stringify(degustRes.data[0]));
      if (linxRes.data?.[0]) console.log('[useProductionForecast] Linx sample:', JSON.stringify(linxRes.data[0]));
      // Contar quantas vendas de ontem existem em cada fonte
      const degustYesterday = (degustRes.data || []).filter(s => String(s.data).split('T')[0] === yesterdayStr);
      const linxYesterday = (linxRes.data || []).filter(s => String(s.data).split('T')[0] === yesterdayStr);
      console.log(`[useProductionForecast] Ontem (${yesterdayStr}): Degust=${degustYesterday.length} rows, Linx=${linxYesterday.length} rows`);

      if (salesRes.error) throw salesRes.error;
      const salesData = salesRes.data || [];
      const emptyResult = {
        items: [], abcCurve: [], dowName, dataRange: '', yesterdayDate: yesterdayStr, coverageDays,
        assessment: { totalProdutos: 0, criticos: 0, baixos: 0, ok: 0, cobertos: 0, demandaTotalOntem: 0, topCriticos: [], topVendidos: [] },
      };
      if (salesData.length === 0) return emptyResult;

      // Produtos ativos
      const productIds = [...new Set(salesData.map(s => s.produto_master_id).filter(Boolean))];
      const { data: products, error: prodError } = await supabase
        .from('produtos_master')
        .select('id, nome, setor')
        .eq('ativo', true)
        .in('setor', ['PRODUTOS', 'CÂMARA FRIA', 'Câmara Fria'])
        .in('id', productIds);
      if (prodError) throw prodError;
      const productMap = new Map(products?.map(p => [p.id, p]) || []);

      // Estoque fábrica
      const stockMap = new Map<number, number>();
      for (const s of stockRes.data || []) {
        if (s.produto_master_id) stockMap.set(s.produto_master_id, Number(s.quantidade_atual) || 0);
      }

      // Passo 1: Agregar por (produto × data) — SOMA cross-lojas
      // Isso dá a demanda total da fábrica por produto em cada dia
      const productDateTotal = new Map<number, Map<string, number>>(); // pid → date → qty_total_fabrica
      const yesterdayByProductLoja = new Map<string, number>();
      const productRevenue = new Map<number, number>(); // faturamento 60d
      const productQtdTotal = new Map<number, number>(); // quantidade 60d

      for (const sale of salesData) {
        const pid = sale.produto_master_id;
        if (!pid || !productMap.has(pid)) continue;
        const qty = Number(sale.quantidade) || 0;

        // Acumular faturamento e quantidade totais
        productRevenue.set(pid, (productRevenue.get(pid) || 0) + (Number(sale.valor_total) || 0));
        productQtdTotal.set(pid, (productQtdTotal.get(pid) || 0) + qty);

        // Agregar por data (soma cross-lojas)
        const saleDateNorm = String(sale.data).split('T')[0];
        if (!productDateTotal.has(pid)) productDateTotal.set(pid, new Map());
        const dateMap = productDateTotal.get(pid)!;
        dateMap.set(saleDateNorm, (dateMap.get(saleDateNorm) || 0) + qty);

        // Vendas de ontem por loja (pra breakdown na UI)
        // Normalizar data: Supabase pode retornar "2026-04-08" ou "2026-04-08T00:00:00+00:00"
        const saleDataStr = String(sale.data).split('T')[0];
        if (saleDataStr === yesterdayStr) {
          const key = `${pid}-${sale.loja_id}`;
          yesterdayByProductLoja.set(key, (yesterdayByProductLoja.get(key) || 0) + qty);
        }
      }

      // Passo 2: Agrupar por dia da semana — MÉDIA dos totais diários
      type DowEntry = { total: number; count: number };
      const productDowMap = new Map<number, Map<number, DowEntry>>();
      const productTotalDays = new Map<number, Set<string>>();

      for (const [pid, dateMap] of productDateTotal) {
        if (!productDowMap.has(pid)) productDowMap.set(pid, new Map());
        const dowMap = productDowMap.get(pid)!;
        if (!productTotalDays.has(pid)) productTotalDays.set(pid, new Set());
        const daysSet = productTotalDays.get(pid)!;

        for (const [date, qtyTotal] of dateMap) {
          daysSet.add(date);
          const saleDate = new Date(date + 'T12:00:00');
          const saleDow = saleDate.getDay();
          if (!dowMap.has(saleDow)) dowMap.set(saleDow, { total: 0, count: 0 });
          const entry = dowMap.get(saleDow)!;
          entry.total += qtyTotal; // já é soma cross-lojas
          entry.count += 1; // conta 1 dia
        }
      }

      // Calcular previsão
      const items: ForecastItem[] = [];

      for (const [pid, dowMap] of productDowMap) {
        const product = productMap.get(pid);
        if (!product) continue;

        // Média geral da demanda total diária (fábrica, todas as lojas somadas)
        let totalAll = 0; let countAll = 0;
        for (const [, e] of dowMap) { totalAll += e.total; countAll += e.count; }
        const mediaGeral = countAll > 0 ? totalAll / countAll : 0;

        // Média para o dia da semana de hoje
        const todayDow = dowMap.get(dow);
        const demandaDiariaHoje = todayDow && todayDow.count > 0
          ? todayDow.total / todayDow.count
          : mediaGeral;

        const fatorDia = mediaGeral > 0 ? demandaDiariaHoje / mediaGeral : 1;

        // Demanda diária = soma de todas as lojas (fábrica precisa abastecer todas)
        const demandaDiariaTotal = Math.ceil(demandaDiariaHoje);

        if (demandaDiariaTotal <= 0) continue;

        // Estoque fábrica
        const estoqueFabrica = stockMap.get(pid) || 0;

        // Cobertura = estoque ÷ demanda_diaria_total
        const coberturaDias = demandaDiariaTotal > 0
          ? estoqueFabrica / demandaDiariaTotal
          : 99;

        // Sugestão = o que falta para atingir X dias de cobertura
        const estoqueNecessario = demandaDiariaTotal * coverageDays;
        const sugestao = Math.max(0, Math.ceil(estoqueNecessario - estoqueFabrica));

        // Vendas por loja ontem (todas as 5 lojas: 2=Asa Sul, 3=Asa Norte, 4=Lago Sul, 5=Águas Claras, 6=BSB Shopping)
        const vendasPorLoja: StoreSales[] = [];
        let vendasOntemTotal = 0;
        const ALL_LOJA_IDS = [2, 3, 4, 5, 6];
        for (const lojaId of ALL_LOJA_IDS) {
          const key = `${pid}-${lojaId}`;
          const qty = yesterdayByProductLoja.get(key) || 0;
          vendasOntemTotal += qty;
          vendasPorLoja.push({
            loja_id: lojaId,
            loja_nome: LOJA_NAMES[lojaId] || `Loja ${lojaId}`,
            vendas_ontem: qty,
            media_diaria: Math.round((demandaDiariaHoje / ALL_LOJA_IDS.length) * 10) / 10,
          });
        }

        items.push({
          produto_master_id: pid,
          nome: product.nome,
          setor: product.setor || '',
          demanda_diaria_media: Math.round(demandaDiariaHoje * 10) / 10,
          demanda_diaria_total: demandaDiariaTotal,
          fator_dia: Math.round(fatorDia * 100) / 100,
          vendas_ontem_total: vendasOntemTotal,
          vendas_por_loja: vendasPorLoja,
          estoque_fabrica: estoqueFabrica,
          cobertura_dias: Math.round(coberturaDias * 10) / 10,
          sugestao_producao: sugestao,
          dias_dados: productTotalDays.get(pid)?.size || 0,
          faturamento_60d: productRevenue.get(pid) || 0,
          curva: 'C' as const, // será preenchido abaixo
          pct_faturamento: 0,
        });
      }

      // Calcular curva ABC por QUANTIDADE vendida (volume de produção)
      const totalQtd = items.reduce((s, i) => s + (productQtdTotal.get(i.produto_master_id) || 0), 0);
      const byQtd = [...items].sort((a, b) =>
        (productQtdTotal.get(b.produto_master_id) || 0) - (productQtdTotal.get(a.produto_master_id) || 0)
      );
      let cumPct = 0;
      for (const item of byQtd) {
        const qtd60d = productQtdTotal.get(item.produto_master_id) || 0;
        const pct = totalQtd > 0 ? (qtd60d / totalQtd) * 100 : 0;
        cumPct += pct;
        item.faturamento_60d = qtd60d; // reutilizando o campo como qtd_60d
        item.pct_faturamento = Math.round(pct * 10) / 10;
        if (cumPct <= 80) item.curva = 'A';
        else if (cumPct <= 95) item.curva = 'B';
        else item.curva = 'C';
      }

      // Curva ABC para o termômetro
      const abcCurve: AbcItem[] = byQtd.map(i => ({
        produto_master_id: i.produto_master_id,
        nome: i.nome,
        faturamento: Math.round(i.faturamento_60d), // na verdade é qtd vendida
        pct: i.pct_faturamento,
        curva: i.curva,
      }));

      // Sort por cobertura (mais urgente primeiro)
      items.sort((a, b) => a.cobertura_dias - b.cobertura_dias);

      // Assessment
      const criticos = items.filter(i => i.cobertura_dias < 1);
      const baixos = items.filter(i => i.cobertura_dias >= 1 && i.cobertura_dias < 2);
      const ok = items.filter(i => i.cobertura_dias >= 2 && i.cobertura_dias < 4);
      const cobertos = items.filter(i => i.cobertura_dias >= 4);
      const demandaTotalOntem = items.reduce((s, i) => s + i.vendas_ontem_total, 0);

      const byVendasOntem = [...items].sort((a, b) => b.vendas_ontem_total - a.vendas_ontem_total);

      const assessment: ForecastAssessment = {
        totalProdutos: items.length,
        criticos: criticos.length,
        baixos: baixos.length,
        ok: ok.length,
        cobertos: cobertos.length,
        demandaTotalOntem: demandaTotalOntem,
        topCriticos: criticos.slice(0, 3).map(i => i.nome),
        topVendidos: byVendasOntem.slice(0, 3).map(i => `${i.nome} (${i.vendas_ontem_total})`),
      };

      const dates = salesData.map(s => s.data).sort();
      const dataRange = dates.length > 0 ? `${dates[0]} a ${dates[dates.length - 1]}` : '';

      return { items, abcCurve, assessment, dowName, dataRange, yesterdayDate: yesterdayStr, coverageDays };
    },
    staleTime: 1000 * 60 * 30,
  });
}

