291	interface CartEntry {
292	  produto_master_id: number;
293	  nome: string;
294	  sugestao: number;
295	  quantidade: number;
296	}
297	
298	interface Props {
299	  onSendToPlan?: (items: Array<{ produto_master_id: number; nome: string; quantidade: number }>) => void;
300	}
301	
302	export function ProductionForecastTab({ onSendToPlan }: Props) {
303	  const [coverageDays, setCoverageDays] = useState(3);
304	  const { data, isLoading, error } = useProductionForecast(coverageDays);
305	  const [search, setSearch] = useState('');
306	  const [cart, setCart] = useState<CartEntry[]>([]);
307	
308	  const cartIds = useMemo(() => new Set(cart.map(c => c.produto_master_id)), [cart]);
309	
310	  const filtered = useMemo(() => {
311	    if (!data) return [];
312	    const term = search.toLowerCase();
313	    return term ? data.items.filter(i => i.nome.toLowerCase().includes(term)) : data.items;
314	  }, [data, search]);
315	
316	  const addToCart = useCallback((item: ForecastItem) => {
317	    setCart(prev => {
318	      if (prev.some(c => c.produto_master_id === item.produto_master_id))
319	        return prev.filter(c => c.produto_master_id !== item.produto_master_id);
320	      return [...prev, {
321	        produto_master_id: item.produto_master_id,
322	        nome: item.nome,
323	        sugestao: item.sugestao_producao,
324	        quantidade: item.sugestao_producao > 0 ? item.sugestao_producao : item.demanda_diaria_total,
325	      }];
326	    });
327	  }, []);
328	
329	  const updateQty = useCallback((pid: number, qty: number) => {
330	    setCart(prev => prev.map(c => c.produto_master_id === pid ? { ...c, quantidade: qty } : c));
331	  }, []);
332	
333	  const removeFromCart = useCallback((pid: number) => {
334	    setCart(prev => prev.filter(c => c.produto_master_id !== pid));
335	  }, []);
336	
337	  const addAllUrgent = useCallback(() => {
338	    if (!data) return;
339	    const urgent = data.items.filter(i =>
340	      i.cobertura_dias < 2 && i.sugestao_producao > 0 && !cartIds.has(i.produto_master_id)
341	    );
342	    setCart(prev => [...prev, ...urgent.map(i => ({
343	      produto_master_id: i.produto_master_id,
344	      nome: i.nome,
345	      sugestao: i.sugestao_producao,
346	      quantidade: i.sugestao_producao,
347	    }))]);
348	  }, [data, cartIds]);
349	
350	  const handleGenerate = useCallback(() => {
351	    if (!onSendToPlan || cart.length === 0) return;
352	    onSendToPlan(cart.filter(c => c.quantidade > 0).map(c => ({
353	      produto_master_id: c.produto_master_id, nome: c.nome, quantidade: c.quantidade,
354	    })));
355	  }, [cart, onSendToPlan]);
356	
357	  const totalQty = cart.reduce((s, c) => s + c.quantidade, 0);
358	
359	  if (isLoading) {
360	    return (
361	      <div className="space-y-4">
362	        <Skeleton className="h-28 rounded-xl" />
363	        <Skeleton className="h-6 rounded-lg" />
364	        <div className="grid grid-cols-1 lg:grid-cols-[1fr_340px] gap-6">
365	          <div className="space-y-3">{Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-28 rounded-xl" />)}</div>
366	          <Skeleton className="h-64 rounded-xl" />
367	        </div>
368	      </div>
369	    );
370	  }
371	
372	  if (error) return <p className="text-center py-12 text-destructive">Erro: {(error as Error).message}</p>;
373	
374	  if (!data || data.items.length === 0) {
375	    return (
376	      <div className="text-center py-16 text-muted-foreground">
377	        <ClipboardList className="h-12 w-12 mx-auto mb-3 opacity-30" />
378	        <p className="font-medium">Sem dados de vendas</p>
379	        <p className="text-xs mt-1">Verifique a integração Degust.</p>
380	      </div>
381	    );
382	  }
383	
384	  return (
385	    <div className="space-y-4">
386	      {/* Assessment */}
387	      <AssessmentBanner
388	        assessment={data.assessment}
389	        dowName={data.dowName}
390	        coverageDays={coverageDays}
391	        onChangeCoverage={setCoverageDays}
392	      />
393	
394	      {/* ABC Heatbar */}
395	      <AbcHeatbar items={data.abcCurve} />
396	
397	      {/* Search */}
398	      <div className="flex items-center gap-2">
399	        <div className="relative flex-1">
400	          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
401	          <Input data-mia-field="search" placeholder="Buscar produto..." value={search} onChange={(e) => setSearch(e.target.value)}
402	            className="pl-10 h-9 text-sm rounded-lg" />
403	        </div>
404	        {data.assessment.criticos + data.assessment.baixos > 0 && (
405	          <Button data-mia-action="add-all-urgent" variant="outline" size="sm" onClick={addAllUrgent} className="text-xs shrink-0">
406	            + Urgentes
407	          </Button>
408	        )}
409	      </div>
410	
411	      {/* Split layout */}
412	      <div className="grid grid-cols-1 lg:grid-cols-[1fr_340px] gap-6 items-start">
413	        {/* LEFT: Products */}
414	        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-[calc(100vh-420px)] overflow-y-auto pr-1">
415	          {filtered.map(item => (
416	            <ProductCard key={item.produto_master_id} item={item}
417	              inCart={cartIds.has(item.produto_master_id)} onAdd={() => addToCart(item)} />
418	          ))}
419	        </div>
420	
421	        {/* RIGHT: Cart */}
422	        <div className="lg:sticky lg:top-4">
423	          <div className="rounded-xl border border-border bg-card p-4 space-y-3">
424	            <div className="flex items-center justify-between">
425	              <h4 className="font-semibold text-sm flex items-center gap-2">
426	                <ShoppingCart className="h-4 w-4 text-[#57715B]" />
427	                Ordem de Produção
428	              </h4>
429	              {cart.length > 0 && (
430	                <Badge variant="secondary" className="text-xs tabular-nums">
431	                  {cart.length} · {totalQty} un
432	                </Badge>
433	              )}
434	            </div>
435	
436	            {cart.length === 0 ? (
437	              <div className="text-center py-8 text-muted-foreground">
438	                <ShoppingCart className="h-8 w-8 mx-auto mb-2 opacity-20" />
439	                <p className="text-xs">Clique nos produtos à esquerda</p>
440	              </div>
441	            ) : (
442	              <>
443	                <div className="max-h-[calc(100vh-480px)] overflow-y-auto">
444	                  {cart.map(e => (
445	                    <CartItem key={e.produto_master_id} nome={e.nome} sugestao={e.sugestao}
446	                      quantidade={e.quantidade} onChange={q => updateQty(e.produto_master_id, q)}
447	                      onRemove={() => removeFromCart(e.produto_master_id)} />
448	                  ))}
449	                </div>
450	                <Button data-mia-action="generate" onClick={handleGenerate} disabled={!onSendToPlan}
451	                  className="w-full bg-[#57715B] hover:bg-[#4a6350] text-white rounded-xl h-11 text-sm font-medium">
452	                  Gerar Ordens ({cart.length})
453	                  <ArrowRight className="ml-2 h-4 w-4" />
454	                </Button>
455	              </>
456	            )}
457	          </div>
458	        </div>
459	      </div>
460	    </div>
461	  );
462	}
