import { useState, useCallback, useMemo } from 'react';
import { useProductionForecast, ForecastItem, AbcItem } from '../hooks/useProductionForecast';
import { Input } from '@/shared/ui/input';
import { Button } from '@/shared/ui/button';
import { Skeleton } from '@/shared/ui/skeleton';
import { Badge } from '@/shared/ui/badge';
import {
  Search,
  Plus,
  Minus,
  Trash2,
  ArrowRight,
  ClipboardList,
  AlertTriangle,
  CheckCircle2,
  ShoppingCart,
} from 'lucide-react';
import { cn } from '@/shared/lib/utils';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/shared/ui/tooltip';

// --- Assessment ---

function AssessmentBanner({
  assessment,
  dowName,
  coverageDays,
  onChangeCoverage,
}: {
  assessment: {
    criticos: number;
    baixos: number;
    ok: number;
    cobertos: number;
    demandaTotalOntem: number;
    topCriticos: string[];
    topVendidos: string[];
  };
  dowName: string;
  coverageDays: number;
  onChangeCoverage: (d: number) => void;
}) {
  const hasCritical = assessment.criticos > 0;

  return (
    <div className={cn(
      'rounded-xl p-4 space-y-3 border',
      hasCritical
        ? 'bg-red-50/60 dark:bg-red-950/15 border-red-200/50 dark:border-red-800/30'
        : 'bg-[#57715B]/5 dark:bg-[#57715B]/10 border-[#57715B]/20'
    )}>
      <div className="space-y-1 text-sm leading-relaxed">
        <p className="font-semibold text-base">
          {hasCritical ? '⚠️' : '📋'} Análise — {dowName}
        </p>
        <p>
          Ontem: <strong>{assessment.demandaTotalOntem} un vendidas</strong> (5 lojas).
          {assessment.topVendidos.length > 0 && (
            <> Mais vendidos: <strong>{assessment.topVendidos.join(', ')}</strong>.</>
          )}
        </p>
        {assessment.criticos > 0 && (
          <p className="text-red-700 dark:text-red-400 font-medium">
            <AlertTriangle className="inline h-3.5 w-3.5 mr-1 -mt-0.5" />
            {assessment.criticos} produto{assessment.criticos > 1 ? 's' : ''} com {'<'}1 dia de estoque
            {assessment.topCriticos.length > 0 && <>: <strong>{assessment.topCriticos.join(', ')}</strong></>}.
          </p>
        )}
        {assessment.baixos > 0 && (
          <p className="text-amber-700 dark:text-amber-400 text-xs">
            {assessment.baixos} com 1-2 dias de estoque.
          </p>
        )}
      </div>

      <div className="flex items-center gap-3 pt-1 border-t border-border/30">
        <span className="text-xs text-muted-foreground shrink-0">Meta de estoque:</span>
        <div className="flex gap-1">
          {[2, 3, 5, 7].map(d => (
            <button
              key={d}
              onClick={() => onChangeCoverage(d)}
              className={cn(
                'px-3 py-1 text-xs font-medium rounded-lg transition-all',
                coverageDays === d
                  ? 'bg-[#57715B] text-white'
                  : 'bg-white/60 dark:bg-white/10 text-muted-foreground hover:bg-white/80'
              )}
            >
              {d}d
            </button>
          ))}
        </div>
        <span className="text-[10px] text-muted-foreground">
          = quanto produzir para durar {coverageDays} dias
        </span>
      </div>
    </div>
  );
}

// --- ABC Heatbar ---

function AbcHeatbar({ items }: { items: AbcItem[] }) {
  if (items.length === 0) return null;

  const maxFat = items[0]?.faturamento || 1;

  return (
    <div className="space-y-1.5">
      <div className="flex items-center justify-between text-[10px] text-muted-foreground">
        <span>Curva ABC — produtos por volume vendido (60 dias)</span>
        <div className="flex items-center gap-3">
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-emerald-500" /> A (80%)</span>
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-amber-400" /> B (15%)</span>
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-gray-300" /> C (5%)</span>
        </div>
      </div>
      <div className="flex gap-[1px] h-6 rounded-lg overflow-hidden">
        {items.map(item => {
          const width = Math.max((item.faturamento / maxFat) * 100, 1.5);
          const color = item.curva === 'A'
            ? 'bg-emerald-500 hover:bg-emerald-400'
            : item.curva === 'B'
              ? 'bg-amber-400 hover:bg-amber-300'
              : 'bg-gray-300 hover:bg-gray-200 dark:bg-gray-600';

          return (
            <Tooltip key={item.produto_master_id}>
              <TooltipTrigger asChild>
                <div
                  className={cn('h-full transition-colors cursor-default', color)}
                  style={{ width: `${width}%`, minWidth: '2px' }}
                />
              </TooltipTrigger>
              <TooltipContent side="bottom" className="text-xs">
                <p className="font-semibold">{item.nome}</p>
                <p>{item.faturamento.toLocaleString('pt-BR')} un · {item.pct}% do volume · Curva {item.curva}</p>
              </TooltipContent>
            </Tooltip>
          );
        })}
      </div>
    </div>
  );
}

// --- Product Card ---

function ProductCard({
  item,
  inCart,
  onAdd,
}: {
  item: ForecastItem;
  inCart: boolean;
  onAdd: () => void;
}) {
  const isCritical = item.cobertura_dias < 1;
  const isLow = item.cobertura_dias >= 1 && item.cobertura_dias < 2;

  return (
    <div
      className={cn(
        'rounded-xl p-3 transition-all cursor-pointer border',
        inCart
          ? 'border-[#57715B] bg-[#57715B]/5 dark:bg-[#57715B]/10 ring-1 ring-[#57715B]/30'
          : 'border-border/50 hover:border-[#57715B]/40 bg-card/50',
        isCritical && !inCart && 'border-l-4 border-l-red-500 bg-red-50/50 dark:bg-red-950/15',
        isLow && !inCart && 'border-l-4 border-l-amber-400 bg-amber-50/30 dark:bg-amber-950/10',
        item.cobertura_dias >= 4 && !inCart && 'opacity-50',
      )}
      onClick={onAdd}
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-2 mb-2">
        <div className="flex items-center gap-2 min-w-0">
          <Badge variant="outline" className={cn(
            'text-[9px] px-1.5 py-0 shrink-0',
            item.curva === 'A' ? 'border-emerald-400 text-emerald-700' :
            item.curva === 'B' ? 'border-amber-400 text-amber-700' :
            'border-gray-300 text-gray-500'
          )}>
            {item.curva}
          </Badge>
          <h4 className="text-sm font-semibold text-foreground leading-tight truncate">{item.nome}</h4>
        </div>
        <div className="flex items-center gap-1.5 shrink-0">
          {isCritical && <AlertTriangle className="h-3.5 w-3.5 text-red-500" />}
          {inCart && <CheckCircle2 className="h-4 w-4 text-[#57715B]" />}
        </div>
      </div>

      {/* Data grid */}
      <div className="grid grid-cols-3 gap-3 text-[11px]">
        {/* Vendas ontem */}
        <div>
          <p className="text-muted-foreground font-medium mb-0.5">Vendas ontem</p>
          {item.vendas_por_loja.map(l => (
            <p key={l.loja_id} className="tabular-nums">
              {l.loja_nome.replace('Águas Claras', 'Á.Claras')}: <strong>{l.vendas_ontem}</strong>
            </p>
          ))}
          <p className="font-bold mt-0.5 pt-0.5 border-t border-border/30">
            Total: {item.vendas_ontem_total}
          </p>
        </div>

        {/* Estoque + Cobertura */}
        <div>
          <p className="text-muted-foreground font-medium mb-0.5">Estoque fábrica</p>
          <p className="text-lg font-bold tabular-nums">{item.estoque_fabrica}</p>
          <p className={cn(
            'text-xs font-semibold',
            isCritical ? 'text-red-600' : isLow ? 'text-amber-600' : 'text-emerald-600'
          )}>
            {item.cobertura_dias < 99 ? `~${item.cobertura_dias} dias` : 'Coberto'}
          </p>
        </div>

        {/* Sugestão */}
        <div>
          <p className="text-muted-foreground font-medium mb-0.5">Produzir</p>
          {item.sugestao_producao > 0 ? (
            <p className="text-lg font-bold tabular-nums text-[#57715B] dark:text-emerald-400">
              {item.sugestao_producao}
            </p>
          ) : (
            <p className="text-lg font-bold tabular-nums text-muted-foreground">—</p>
          )}
          <p className="text-muted-foreground text-[10px]">
            {item.demanda_diaria_total}/dia demanda
          </p>
        </div>
      </div>
    </div>
  );
}

// --- Cart Item ---

function CartItem({
  nome,
  sugestao,
  quantidade,
  onChange,
  onRemove,
}: {
  nome: string;
  sugestao: number;
  quantidade: number;
  onChange: (qty: number) => void;
  onRemove: () => void;
}) {
  return (
    <div className="flex items-center gap-2 py-2.5 border-b border-dashed border-border/40 last:border-0">
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{nome}</p>
        <p className="text-[10px] text-muted-foreground">Sugerido: {sugestao}</p>
      </div>
      <div className="flex items-center gap-1 shrink-0">
        <Button variant="ghost" size="icon" className="h-7 w-7"
          onClick={() => onChange(Math.max(1, quantidade - 10))}>
          <Minus className="h-3 w-3" />
        </Button>
        <Input data-mia-field="search"
          type="number"
          value={quantidade}
          onChange={e => onChange(Math.max(0, Number(e.target.value) || 0))}
          className="w-16 h-7 text-center text-sm font-bold tabular-nums p-0"
        />
        <Button variant="ghost" size="icon" className="h-7 w-7"
          onClick={() => onChange(quantidade + 10)}>
          <Plus className="h-3 w-3" />
        </Button>
        <Button data-mia-action="on-remove"
            data-mia-expects-toast="remov" variant="ghost" size="icon" className="h-7 w-7 text-red-500 hover:text-red-600"
          onClick={onRemove}>
          <Trash2 className="h-3 w-3" />
        </Button>
      </div>
    </div>
  );
}

// --- Main ---

interface CartEntry {
  produto_master_id: number;
  nome: string;
  sugestao: number;
  quantidade: number;
}

interface Props {
  onSendToPlan?: (items: Array<{ produto_master_id: number; nome: string; quantidade: number }>) => void;
}

export function ProductionForecastTab({ onSendToPlan }: Props) {
  const [coverageDays, setCoverageDays] = useState(3);
  const { data, isLoading, error } = useProductionForecast(coverageDays);
  const [search, setSearch] = useState('');
  const [cart, setCart] = useState<CartEntry[]>([]);

  const cartIds = useMemo(() => new Set(cart.map(c => c.produto_master_id)), [cart]);

  const filtered = useMemo(() => {
    if (!data) return [];
    const term = search.toLowerCase();
    return term ? data.items.filter(i => i.nome.toLowerCase().includes(term)) : data.items;
  }, [data, search]);

  const addToCart = useCallback((item: ForecastItem) => {
    setCart(prev => {
      if (prev.some(c => c.produto_master_id === item.produto_master_id))
        return prev.filter(c => c.produto_master_id !== item.produto_master_id);
      return [...prev, {
        produto_master_id: item.produto_master_id,
        nome: item.nome,
        sugestao: item.sugestao_producao,
        quantidade: item.sugestao_producao > 0 ? item.sugestao_producao : item.demanda_diaria_total,
      }];
    });
  }, []);

  const updateQty = useCallback((pid: number, qty: number) => {
    setCart(prev => prev.map(c => c.produto_master_id === pid ? { ...c, quantidade: qty } : c));
  }, []);

  const removeFromCart = useCallback((pid: number) => {
    setCart(prev => prev.filter(c => c.produto_master_id !== pid));
  }, []);

  const addAllUrgent = useCallback(() => {
    if (!data) return;
    const urgent = data.items.filter(i =>
      i.cobertura_dias < 2 && i.sugestao_producao > 0 && !cartIds.has(i.produto_master_id)
    );
    setCart(prev => [...prev, ...urgent.map(i => ({
      produto_master_id: i.produto_master_id,
      nome: i.nome,
      sugestao: i.sugestao_producao,
      quantidade: i.sugestao_producao,
    }))]);
  }, [data, cartIds]);

  const handleGenerate = useCallback(() => {
    if (!onSendToPlan || cart.length === 0) return;
    onSendToPlan(cart.filter(c => c.quantidade > 0).map(c => ({
      produto_master_id: c.produto_master_id, nome: c.nome, quantidade: c.quantidade,
    })));
  }, [cart, onSendToPlan]);

  const totalQty = cart.reduce((s, c) => s + c.quantidade, 0);

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-28 rounded-xl" />
        <Skeleton className="h-6 rounded-lg" />
        <div className="grid grid-cols-1 lg:grid-cols-[1fr_340px] gap-6">
          <div className="space-y-3">{Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-28 rounded-xl" />)}</div>
          <Skeleton className="h-64 rounded-xl" />
        </div>
      </div>
    );
  }

  if (error) return <p className="text-center py-12 text-destructive">Erro: {(error as Error).message}</p>;

  if (!data || data.items.length === 0) {
    return (
      <div className="text-center py-16 text-muted-foreground">
        <ClipboardList className="h-12 w-12 mx-auto mb-3 opacity-30" />
        <p className="font-medium">Sem dados de vendas</p>
        <p className="text-xs mt-1">Verifique a integração Degust.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Assessment */}
      <AssessmentBanner
        assessment={data.assessment}
        dowName={data.dowName}
        coverageDays={coverageDays}
        onChangeCoverage={setCoverageDays}
      />

      {/* ABC Heatbar */}
      <AbcHeatbar items={data.abcCurve} />

      {/* Search */}
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input data-mia-field="search" placeholder="Buscar produto..." value={search} onChange={(e) => setSearch(e.target.value)}
            className="pl-10 h-9 text-sm rounded-lg" />
        </div>
        {data.assessment.criticos + data.assessment.baixos > 0 && (
          <Button data-mia-action="add-all-urgent" variant="outline" size="sm" onClick={addAllUrgent} className="text-xs shrink-0">
            + Urgentes
          </Button>
        )}
      </div>

      {/* Split layout */}
      <div className="grid grid-cols-1 lg:grid-cols-[1fr_340px] gap-6 items-start">
        {/* LEFT: Products */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-[calc(100vh-420px)] overflow-y-auto pr-1">
          {filtered.map(item => (
            <ProductCard key={item.produto_master_id} item={item}
              inCart={cartIds.has(item.produto_master_id)} onAdd={() => addToCart(item)} />
          ))}
        </div>

        {/* RIGHT: Cart */}
        <div className="lg:sticky lg:top-4">
          <div className="rounded-xl border border-border bg-card p-4 space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="font-semibold text-sm flex items-center gap-2">
                <ShoppingCart className="h-4 w-4 text-[#57715B]" />
                Ordem de Produção
              </h4>
              {cart.length > 0 && (
                <Badge variant="secondary" className="text-xs tabular-nums">
                  {cart.length} · {totalQty} un
                </Badge>
              )}
            </div>

            {cart.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <ShoppingCart className="h-8 w-8 mx-auto mb-2 opacity-20" />
                <p className="text-xs">Clique nos produtos à esquerda</p>
              </div>
            ) : (
              <>
                <div className="max-h-[calc(100vh-480px)] overflow-y-auto">
                  {cart.map(e => (
                    <CartItem key={e.produto_master_id} nome={e.nome} sugestao={e.sugestao}
                      quantidade={e.quantidade} onChange={q => updateQty(e.produto_master_id, q)}
                      onRemove={() => removeFromCart(e.produto_master_id)} />
                  ))}
                </div>
                <Button data-mia-action="generate" onClick={handleGenerate} disabled={!onSendToPlan}
                  className="w-full bg-[#57715B] hover:bg-[#4a6350] text-white rounded-xl h-11 text-sm font-medium">
                  Gerar Ordens ({cart.length})
                  <ArrowRight className="ml-2 h-4 w-4" />
                </Button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

