      <TooltipContent side="bottom" className="max-w-[240px] text-xs">
        <p className="font-semibold">Curva {entry.curva}</p>
        <p className="text-muted-foreground">{style.label}.</p>
        <p className="mt-1">
          Faturamento {brl(entry.faturamento)} · {entry.pctFaturamento}% da loja
          {' '}· acumulado {entry.pctAcumulado}% · #{entry.rank}
        </p>
        {margem !== null && (
          <p className="mt-0.5">
            Margem bruta média: <strong>{margem.toFixed(0)}%</strong>
          </p>
        )}
      </TooltipContent>
    </Tooltip>
  );
});

