/**
 * @module abc
 *
 * Cálculo puro da Curva ABC (Pareto) de produtos a partir de vendas reais.
 *
 * A classificação é por **faturamento** (valor_total das vendas Degust/POS),
 * que é o critério clássico de ABC para varejo: poucos itens (A) concentram a
 * maior parte da receita. Quando não há faturamento (só volume sem valor), o
 * cálculo cai para classificação por **volume** para não jogar tudo em C.
 *
 * Sem dependência de React/Supabase — testável isoladamente.
 */

/** Linha de venda agregável (uma ou várias por produto). */
export interface AbcSaleRow {
  produto_master_id: number | null;
  quantidade: number | null;
  valor_total: number | null;
}

/** Classe da curva ABC. */
export type AbcCurva = 'A' | 'B' | 'C';

/** Resultado por produto. */
export interface AbcEntry {
  produto_master_id: number;
  /** Soma de unidades vendidas no período. */
  volume: number;
  /** Soma do faturamento (R$) no período. */
  faturamento: number;
  /** Preço de venda médio = faturamento / volume (0 se volume 0). */
  precoVendaMedio: number;
  /** Classe A/B/C. */
  curva: AbcCurva;
  /** Participação deste produto no faturamento total (%). */
  pctFaturamento: number;
  /** Participação acumulada até este produto, ordenado desc (%). */
  pctAcumulado: number;
  /** Posição no ranking de faturamento (1 = maior). */
  rank: number;
  /** Fração da barra (0–1) relativa ao líder — para largura visual. */
  shareOfMax: number;
}

/** Agregado completo da curva. */
export interface AbcResult {
  /** Entradas ordenadas por faturamento desc. */
  entries: AbcEntry[];
  /** Mapa produto_master_id → entrada (para lookup O(1) na lista). */
  byId: Map<number, AbcEntry>;
  totalFaturamento: number;
  totalVolume: number;
  /** Contagem de produtos por classe. */
  counts: { A: number; B: number; C: number };
}

/** Limiares de corte acumulado (clássico 80/95). */
const CORTE_A = 80;
const CORTE_B = 95;

/**
 * Agrega vendas por produto e classifica em curva ABC.
 *
 * @param rows - Linhas de venda (Degust/POS). `produto_master_id` nulo é ignorado.
 * @returns Agregado com entradas ordenadas, mapa de lookup e contagens.
 */
export function computeAbcCurve(rows: AbcSaleRow[]): AbcResult {
  const volumeById = new Map<number, number>();
  const faturamentoById = new Map<number, number>();

  for (const row of rows) {
    const pid = row.produto_master_id;
    if (!pid) continue;
    const qty = Number(row.quantidade) || 0;
    const val = Number(row.valor_total) || 0;
    volumeById.set(pid, (volumeById.get(pid) || 0) + qty);
    faturamentoById.set(pid, (faturamentoById.get(pid) || 0) + val);
  }

  const totalFaturamento = [...faturamentoById.values()].reduce((a, b) => a + b, 0);
  const totalVolume = [...volumeById.values()].reduce((a, b) => a + b, 0);

  // Critério de ordenação: faturamento; fallback para volume se não há receita.
  const usarVolume = totalFaturamento <= 0;
  const total = usarVolume ? totalVolume : totalFaturamento;
  const metricOf = (pid: number) =>
    usarVolume ? volumeById.get(pid) || 0 : faturamentoById.get(pid) || 0;

  const pids = [...volumeById.keys()].sort((a, b) => {
    const diff = metricOf(b) - metricOf(a);
    if (diff !== 0) return diff;
    return (volumeById.get(b) || 0) - (volumeById.get(a) || 0);
  });

  const maxMetric = pids.length > 0 ? metricOf(pids[0]) : 0;

  const entries: AbcEntry[] = [];
  const byId = new Map<number, AbcEntry>();
  const counts = { A: 0, B: 0, C: 0 };
  let cumPct = 0;

  pids.forEach((pid, index) => {
    const volume = volumeById.get(pid) || 0;
    const faturamento = faturamentoById.get(pid) || 0;
    const metric = metricOf(pid);
    const pct = total > 0 ? (metric / total) * 100 : 0;
    cumPct += pct;

    let curva: AbcCurva;
    if (cumPct <= CORTE_A) curva = 'A';
    else if (cumPct <= CORTE_B) curva = 'B';
    else curva = 'C';
    counts[curva] += 1;

    const entry: AbcEntry = {
      produto_master_id: pid,
      volume,
      faturamento,
      precoVendaMedio: volume > 0 ? faturamento / volume : 0,
      curva,
      pctFaturamento: Math.round(pct * 10) / 10,
      pctAcumulado: Math.round(cumPct * 10) / 10,
      rank: index + 1,
      shareOfMax: maxMetric > 0 ? metric / maxMetric : 0,
    };
    entries.push(entry);
    byId.set(pid, entry);
  });

  return { entries, byId, totalFaturamento, totalVolume, counts };
}

