import { memo } from 'react';
import { cn } from '@/shared/lib/utils';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/shared/ui/tooltip';
import type { AbcEntry } from '../lib/abc';

const brl = (v: number) =>
  new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
    minimumFractionDigits: 2,
  }).format(v || 0);

const int = (v: number) => (v || 0).toLocaleString('pt-BR');

/**
 * Tier de impacto financeiro do produto:
 * - prejuizo: margem negativa (perde dinheiro por venda) → vermelho
 * - lucro:    classe A (puxa o resultado) → verde
 * - medio:    classe B → amarelo
 * - baixo:    classe C (pouco giro/lucro) → vermelho suave
 */
function tierOf(entry: AbcEntry): {
  key: 'prejuizo' | 'lucro' | 'medio' | 'baixo';
  label: string;
  badge: string;
  fill: string;
  glow: string;
} {
  if (entry.isPrejuizo) {
    return {
      key: 'prejuizo',
      label: 'Prejuízo',
      badge: 'bg-red-500/15 text-red-600 dark:text-red-400 ring-1 ring-red-500/40',
      fill: 'from-red-500 to-red-700',
      glow: 'shadow-[0_0_8px_rgba(239,68,68,0.5)]',
    };
  }
  if (entry.curva === 'A') {
    return {
      key: 'lucro',
      label: 'Lucro',
      badge: 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400',
      fill: 'from-emerald-400 to-emerald-600',
      glow: 'shadow-[0_0_8px_rgba(16,185,129,0.45)]',
    };
  }
  if (entry.curva === 'B') {
    return {
      key: 'medio',
      label: 'Lucro baixo',
      badge: 'bg-amber-500/15 text-amber-600 dark:text-amber-400',
      fill: 'from-amber-300 to-amber-500',
      glow: '',
    };
  }
  return {
    key: 'baixo',
    label: 'Baixo giro',
    badge: 'bg-red-500/10 text-red-500/80 dark:text-red-400/80',
    fill: 'from-red-300 to-red-500',
    glow: '',
  };
}

interface AbcBarProps {
  /** Entrada ABC do produto (undefined = sem venda no período). */
  entry?: AbcEntry;
  /** Preço de custo de cadastro (fallback para o caso "sem venda"). */
  precoCusto?: number;
  className?: string;
}

/**
 * Indicador de Curva ABC por item — barra verde/amarela/vermelha proporcional
 * ao impacto do produto no LUCRO da loja, com a classe (A/B/C), o tier
 * (Lucro / Lucro baixo / Prejuízo) e infos de custo, venda média e volume.
 */
export const AbcBar = memo(function AbcBar({
  entry,
  precoCusto,
  className,
}: AbcBarProps) {
  // Sem venda no período: estado neutro mas ainda mostra o custo de cadastro.
  if (!entry || entry.volume <= 0) {
    return (
      <div className={cn('min-w-[160px] space-y-1', className)}>
        <div className="flex items-center gap-2">
          <span className="inline-flex h-5 w-7 shrink-0 items-center justify-center rounded-md bg-[#57715B]/8 text-[9px] font-bold text-muted-foreground">
            —
          </span>
          <div className="h-2 flex-1 rounded-full bg-[#57715B]/10" />
        </div>
        <p className="text-[10px] text-muted-foreground">
          Sem venda no período
          {precoCusto ? ` · custo ${brl(precoCusto)}` : ''}
        </p>
      </div>
    );
  }

  const tier = tierOf(entry);
  const width = Math.max(entry.shareOfMax * 100, 5); // mínimo visível
  const custo = entry.custoUnit || precoCusto || 0;
  const margemColor =
    entry.margemPct < 0
      ? 'text-red-600 dark:text-red-400'
      : entry.margemPct < 20
        ? 'text-amber-600 dark:text-amber-400'
        : 'text-emerald-600 dark:text-emerald-400';

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div className={cn('min-w-[160px] space-y-1 cursor-default', className)}>
          <div className="flex items-center gap-2">
            <span
              className={cn(
                'inline-flex h-5 min-w-[28px] shrink-0 items-center justify-center gap-0.5 rounded-md px-1 text-[10px] font-black',
                tier.badge,
              )}
            >
              {entry.curva}
            </span>
            <div className="h-2 flex-1 overflow-hidden rounded-full bg-[#57715B]/10">
              <div
                className={cn(
                  'h-full rounded-full bg-gradient-to-r transition-all',
                  tier.fill,
                  tier.glow,
                )}
                style={{ width: `${width}%` }}
              />
            </div>
            <span
              className={cn(
                'shrink-0 text-[10px] font-bold uppercase tracking-wide',
                tier.key === 'prejuizo'
                  ? 'text-red-600 dark:text-red-400'
                  : tier.key === 'lucro'
                    ? 'text-emerald-600 dark:text-emerald-400'
                    : tier.key === 'medio'
                      ? 'text-amber-600 dark:text-amber-400'
                      : 'text-muted-foreground',
              )}
            >
              {tier.label}
            </span>
          </div>
          <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5 text-[10px] tabular-nums text-muted-foreground">
            <span>
              Custo{' '}
              <strong className="font-semibold text-foreground/80">
                {brl(custo)}
              </strong>
            </span>
            <span className="text-[#57715B]/30">·</span>
            <span>
              Venda{' '}
              <strong className="font-semibold text-[#57715B] dark:text-[#8FAE94]">
                {brl(entry.precoVendaMedio)}
              </strong>
            </span>
            <span className="text-[#57715B]/30">·</span>
            <span>
              Margem{' '}
              <strong className={cn('font-semibold', margemColor)}>
                {entry.margemPct}%
              </strong>
            </span>
            <span className="text-[#57715B]/30">·</span>
            <span>
              Vol{' '}
              <strong className="font-semibold text-foreground/80">
                {int(entry.volume)}
              </strong>
            </span>
          </div>
        </div>
      </TooltipTrigger>
      <TooltipContent side="bottom" className="max-w-[260px] text-xs">
        <p className="font-semibold">
          Curva {entry.curva} · {tier.label}
        </p>
        <p className="mt-1">
          Faturamento {brl(entry.faturamento)} · Custo {brl(entry.custoTotal)}
        </p>
        <p className={entry.lucro < 0 ? 'text-red-400' : 'text-emerald-400'}>
          Lucro {brl(entry.lucro)} · margem {entry.margemPct}%
        </p>
        <p className="mt-0.5 text-muted-foreground">
          {entry.pctImpacto}% do lucro da loja · acumulado {entry.pctAcumulado}%
