import { memo } from 'react';
import { cn } from '@/shared/lib/utils';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/shared/ui/tooltip';
import type { AbcEntry } from '../lib/abc';

const brl = (v: number) =>
  new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
    minimumFractionDigits: 2,
  }).format(v || 0);

const int = (v: number) => (v || 0).toLocaleString('pt-BR');

/** Paleta por classe: A verde · B amarela · C vermelha (pedido do CTO). */
const CURVA_STYLE = {
  A: {
    badge: 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400',
    fill: 'from-emerald-400 to-emerald-600',
    glow: 'shadow-[0_0_8px_rgba(16,185,129,0.45)]',
    label: 'Alta — concentra a maior parte da receita',
  },
  B: {
    badge: 'bg-amber-500/15 text-amber-600 dark:text-amber-400',
    fill: 'from-amber-300 to-amber-500',
    glow: 'shadow-[0_0_8px_rgba(245,158,11,0.4)]',
    label: 'Média — receita intermediária',
  },
  C: {
    badge: 'bg-red-500/15 text-red-600 dark:text-red-400',
    fill: 'from-red-400 to-red-600',
    glow: 'shadow-[0_0_8px_rgba(239,68,68,0.4)]',
    label: 'Baixa — cauda de baixa receita',
  },
} as const;

interface AbcBarProps {
  /** Entrada ABC do produto (undefined = sem venda no período). */
  entry?: AbcEntry;
  /** Preço de custo de cadastro (produtos_master.preco_custo). */
  precoCusto?: number;
  className?: string;
}

/**
 * Barra de Curva ABC por item — progresso verde/amarela/vermelha proporcional
 * à participação do produto na receita da loja, com infos pequenas de custo,
 * preço de venda médio e volume vendido no período.
 */
export const AbcBar = memo(function AbcBar({
  entry,
  precoCusto,
  className,
}: AbcBarProps) {
  // Sem venda no período: estado neutro, sem poluir a lista.
  if (!entry || entry.volume <= 0) {
    return (
      <div className={cn('min-w-[150px] space-y-1', className)}>
        <div className="h-1.5 w-full rounded-full bg-[#57715B]/10" />
        <p className="text-[10px] text-muted-foreground">Sem venda no período</p>
      </div>
    );
  }

  const style = CURVA_STYLE[entry.curva];
  const width = Math.max(entry.shareOfMax * 100, 4); // mínimo visível
  const margem =
    precoCusto && precoCusto > 0 && entry.precoVendaMedio > 0
      ? ((entry.precoVendaMedio - precoCusto) / entry.precoVendaMedio) * 100
      : null;

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div className={cn('min-w-[150px] space-y-1 cursor-default', className)}>
          <div className="flex items-center gap-2">
            <span
              className={cn(
                'inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-md text-[11px] font-black',
                style.badge,
              )}
            >
              {entry.curva}
            </span>
            <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-[#57715B]/10">
              <div
                className={cn(
                  'h-full rounded-full bg-gradient-to-r transition-all',
                  style.fill,
                  entry.curva === 'A' && style.glow,
                )}
                style={{ width: `${width}%` }}
              />
            </div>
            <span className="shrink-0 text-[10px] font-semibold tabular-nums text-muted-foreground">
              {entry.pctFaturamento}%
            </span>
          </div>
          <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5 text-[10px] tabular-nums text-muted-foreground">
            <span>
              Custo{' '}
              <strong className="font-semibold text-foreground/80">
                {precoCusto ? brl(precoCusto) : '—'}
              </strong>
            </span>
            <span className="text-[#57715B]/30">·</span>
            <span>
              Venda{' '}
              <strong className="font-semibold text-[#57715B] dark:text-[#8FAE94]">
                {brl(entry.precoVendaMedio)}
              </strong>
            </span>
            <span className="text-[#57715B]/30">·</span>
            <span>
              Vol{' '}
              <strong className="font-semibold text-foreground/80">
                {int(entry.volume)}
              </strong>
            </span>
          </div>
        </div>
      </TooltipTrigger>
      <TooltipContent side="bottom" className="max-w-[240px] text-xs">
        <p className="font-semibold">Curva {entry.curva}</p>
        <p className="text-muted-foreground">{style.label}.</p>
        <p className="mt-1">
          Faturamento {brl(entry.faturamento)} · {entry.pctFaturamento}% da loja
          {' '}· acumulado {entry.pctAcumulado}% · #{entry.rank}
        </p>
        {margem !== null && (
          <p className="mt-0.5">
            Margem bruta média: <strong>{margem.toFixed(0)}%</strong>
          </p>
        )}
      </TooltipContent>
    </Tooltip>
  );
});

