import jsPDF, { GState } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

/**
 * Gerador de Relatório PDF da Curva ABC por loja.
 *
 * Mesma identidade visual world-class do relatório de Produção Diária
 * (borda Momma green dupla, logo, watermark, header/footer paginado, resumo
 * executivo). Mostra, por produto: classe ABC, volume vendido, preço de custo,
 * preço de venda médio e faturamento — ordenado por faturamento desc.
 */

// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────

export interface AbcReportRow {
  nome: string;
  curva: 'A' | 'B' | 'C';
  volume: number;
  precoCusto: number | null;
  precoVenda: number;
  faturamento: number;
  pctFaturamento: number;
}

export interface GenerateAbcCurvePdfParams {
  rows: AbcReportRow[];
  storeName: string;
  periodLabel: string; // ex.: "Últimos 30 dias"
  counts: { A: number; B: number; C: number };
  totalFaturamento: number;
  totalVolume: number;
}

// ───────────────────────── HELPERS ─────────────────────────

const MOMMA_GREEN: [number, number, number] = [87, 113, 91];
const MOMMA_GREEN_DARK: [number, number, number] = [30, 37, 31];
const MOMMA_GREEN_SOFT: [number, number, number] = [74, 85, 76];
const CURVA_RGB: Record<'A' | 'B' | 'C', [number, number, number]> = {
  A: [16, 185, 129], // emerald
  B: [245, 158, 11], // amber
  C: [239, 68, 68], // red
};

const brl = (v: number | null): string =>
  v === null || v === undefined
    ? '—'
    : v.toLocaleString('pt-BR', {
        style: 'currency',
        currency: 'BRL',
        minimumFractionDigits: 2,
      });

const numberFmt = (v: number): string =>
  (v || 0).toLocaleString('pt-BR', { maximumFractionDigits: 0 });

const loadImage = (url: string): Promise<HTMLImageElement> =>
  new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'Anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Failed to load image: ${url}`));
    img.src = url;
  });

// ───────────────────────── GERADOR ─────────────────────────

export async function generateAbcCurvePdf(
  params: GenerateAbcCurvePdfParams,
): Promise<void> {
  const { rows, storeName, periodLabel, counts, totalFaturamento, totalVolume } =
    params;

  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(
    () => null,
  );
  const watermarkLogo = await loadImage(
    '/logo sistema/android-chrome-512x512.png',
  ).catch(() => null);

  const doc = new jsPDF('p', 'mm', 'a4');
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  const drawPageExtras = (hookData: { pageNumber?: number }) => {
    const currentPage = hookData.pageNumber || 1;

    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
    doc.setLineWidth(0.2);
    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');

    if (logoHeader) {
      const ratio = logoHeader.height / logoHeader.width;
      let expectedWidth = 45;
      let expectedHeight = expectedWidth * ratio;
      if (expectedHeight > 18) {
        expectedHeight = 18;
        expectedWidth = expectedHeight / ratio;
      }
      doc.addImage(logoHeader, 'PNG', 15, 15, expectedWidth, expectedHeight);
    }

    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...MOMMA_GREEN_DARK);
    doc.setFontSize(16);
    doc.text('RELATÓRIO DE CURVA ABC', pageWidth - 15, 20, { align: 'right' });

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...MOMMA_GREEN);
    doc.text('PRODUTOS POR FATURAMENTO — PDV', pageWidth - 15, 25, {
      align: 'right',
    });

    doc.setTextColor(...MOMMA_GREEN_SOFT);
    doc.setFontSize(8);
    doc.text(`Período: ${periodLabel}`, pageWidth - 15, 31, { align: 'right' });
    doc.text(`Unidade: ${storeName}`, pageWidth - 15, 35, { align: 'right' });

    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.line(15, 43, pageWidth - 15, 43);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...MOMMA_GREEN);
    const totalPages = doc.getNumberOfPages();
    doc.text(
      `Curva ABC Momma • Emissão: ${format(new Date(), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })} • Pág. ${currentPage}/${totalPages}`,
      pageWidth / 2,
      pageHeight - 12,
      { align: 'center' },
    );

    if (watermarkLogo) {
      try {
        doc.setGState(new GState({ opacity: 0.08 }));
        const wSize = 200;
        doc.addImage(
          watermarkLogo,
          'PNG',
          (pageWidth - wSize) / 2,
          (pageHeight - wSize) / 2,
          wSize,
          wSize,
        );
        doc.setGState(new GState({ opacity: 1.0 }));
      } catch {
        /* fallback silencioso */
      }
    }
  };

  drawPageExtras({ pageNumber: 1 });

  // ───────────────────────── RESUMO EXECUTIVO ─────────────────────────
  let cursorY = 52;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('RESUMO EXECUTIVO', 15, cursorY);
  cursorY += 5;

  const boxX = 15;
  const boxW = pageWidth - 30;
  const boxH = 22;

  doc.setFillColor(248, 250, 248);
  doc.setDrawColor(...MOMMA_GREEN);
  doc.setLineWidth(0.4);
  doc.roundedRect(boxX, cursorY, boxW, boxH, 2, 2, 'FD');

  const colW = boxW / 4;
  const drawMetric = (
    label: string,
    value: string,
    colIndex: number,
    valueFontSize: number,
    valueColor: [number, number, number] = MOMMA_GREEN_DARK,
  ) => {
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(120, 120, 120);
    doc.text(label, boxX + colW * colIndex + 4, cursorY + 6);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(valueFontSize);
    doc.setTextColor(...valueColor);
    doc.text(value, boxX + colW * colIndex + 4, cursorY + 14);
  };

  drawMetric('FATURAMENTO', brl(totalFaturamento), 0, 12);
  drawMetric('VOLUME VENDIDO', numberFmt(totalVolume), 1, 13);
  drawMetric('PRODUTOS', numberFmt(counts.A + counts.B + counts.C), 2, 13);
  drawMetric(
    'CLASSES A/B/C',
    `${counts.A} / ${counts.B} / ${counts.C}`,
    3,
    13,
  );

  cursorY += boxH + 8;

  // ───────────────────────── TABELA ABC ─────────────────────────
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('PRODUTOS POR FATURAMENTO (A → C)', 15, cursorY);
  cursorY += 3;

  const body = rows.map((r) => [
    r.curva,
    r.nome,
    numberFmt(r.volume),
    brl(r.precoCusto),
    brl(r.precoVenda),
    brl(r.faturamento),
    `${r.pctFaturamento.toLocaleString('pt-BR', { maximumFractionDigits: 1 })}%`,
  ]);

  autoTable(doc, {
    startY: cursorY,
    head: [['ABC', 'Produto', 'Volume', 'Custo', 'Venda', 'Faturamento', '% Fat.']],
    body,
    theme: 'plain',
    styles: {
      fontSize: 8,
      font: 'helvetica',
      cellPadding: { top: 1.8, bottom: 1.8, left: 2, right: 2 },
      textColor: [60, 60, 60],
