import { describe, it, expect } from 'vitest';
import { computeAbcCurve, type AbcSaleRow } from './abc';

describe('computeAbcCurve', () => {
  it('retorna vazio para entrada vazia', () => {
    const r = computeAbcCurve([]);
    expect(r.entries).toHaveLength(0);
    expect(r.totalFaturamento).toBe(0);
    expect(r.totalLucro).toBe(0);
    expect(r.counts).toEqual({ A: 0, B: 0, C: 0 });
    expect(r.prejuizoCount).toBe(0);
  });

  it('agrega múltiplas linhas e calcula custo/lucro/margem', () => {
    const rows: AbcSaleRow[] = [
      { produto_master_id: 1, quantidade: 10, valor_total: 100 },
      { produto_master_id: 1, quantidade: 5, valor_total: 50 },
    ];
    const cost = new Map([[1, 6]]); // custo 6, venda média 10
    const r = computeAbcCurve(rows, cost);
    const e = r.byId.get(1)!;
    expect(e.volume).toBe(15);
    expect(e.faturamento).toBe(150);
    expect(e.precoVendaMedio).toBe(10);
    expect(e.custoTotal).toBe(90);
    expect(e.lucro).toBe(60);
    expect(e.margemPct).toBe(40); // (10-6)/10
    expect(e.isPrejuizo).toBe(false);
  });

  it('marca prejuízo quando custo > preço de venda', () => {
    const rows: AbcSaleRow[] = [
      { produto_master_id: 1, quantidade: 100, valor_total: 1000 }, // venda 10
      { produto_master_id: 2, quantidade: 10, valor_total: 50 }, // venda 5, custo 8 → prejuízo
    ];
    const cost = new Map([
      [1, 4],
      [2, 8],
    ]);
    const r = computeAbcCurve(rows, cost);
    expect(r.byId.get(2)!.isPrejuizo).toBe(true);
    expect(r.byId.get(2)!.margemPct).toBeLessThan(0);
    expect(r.byId.get(2)!.curva).toBe('C'); // lucro negativo → cauda
    expect(r.byId.get(1)!.isPrejuizo).toBe(false);
    expect(r.prejuizoCount).toBe(1);
  });

  it('classifica curva ABC por LUCRO, não por faturamento bruto', () => {
    // pid2 fatura mais, mas com custo altíssimo (margem mínima) → não é A.
    // pid1 fatura menos, mas margem cheia → maior lucro → A.
    const rows: AbcSaleRow[] = [
      { produto_master_id: 1, quantidade: 100, valor_total: 1000 }, // custo 1 → lucro 900
      { produto_master_id: 2, quantidade: 100, valor_total: 2000 }, // custo 19.5 → lucro 50
    ];
    const cost = new Map([
      [1, 1],
      [2, 19.5],
    ]);
    const r = computeAbcCurve(rows, cost);
    expect(r.entries[0].produto_master_id).toBe(1); // maior lucro primeiro
    expect(r.byId.get(1)!.curva).toBe('A');
    expect(r.byId.get(1)!.rank).toBe(1);
    expect(r.byId.get(1)!.shareOfMax).toBe(1);
  });

  it('ignora produto_master_id nulo', () => {
    const rows: AbcSaleRow[] = [
      { produto_master_id: null, quantidade: 99, valor_total: 999 },
      { produto_master_id: 2, quantidade: 1, valor_total: 1 },
    ];
    const r = computeAbcCurve(rows);
    expect(r.entries).toHaveLength(1);
    expect(r.byId.has(2)).toBe(true);
  });

  it('sem custo cai para ABC de faturamento (lucro = faturamento)', () => {
    const rows: AbcSaleRow[] = [
      { produto_master_id: 1, quantidade: 1, valor_total: 80 },
      { produto_master_id: 2, quantidade: 1, valor_total: 14 },
      { produto_master_id: 3, quantidade: 1, valor_total: 6 },
    ];
    const r = computeAbcCurve(rows); // sem costById
    expect(r.byId.get(1)!.curva).toBe('A');
    expect(r.byId.get(2)!.curva).toBe('B');
    expect(r.byId.get(3)!.curva).toBe('C');
    expect(r.byId.get(1)!.margemPct).toBe(100); // custo 0
  });

  it('pctAcumulado é monotônico sobre as contribuições positivas', () => {
    const rows: AbcSaleRow[] = [
      { produto_master_id: 1, quantidade: 1, valor_total: 70 },
      { produto_master_id: 2, quantidade: 1, valor_total: 20 },
      { produto_master_id: 3, quantidade: 1, valor_total: 10 },
    ];
    const r = computeAbcCurve(rows);
    const acc = r.entries.map((e) => e.pctAcumulado);
    expect(acc[0]).toBeLessThanOrEqual(acc[1]);
    expect(acc[1]).toBeLessThanOrEqual(acc[2]);
    expect(acc[acc.length - 1]).toBeCloseTo(100, 1);
  });
});

/**
 * @module abc
 *
 * Cálculo puro da Curva ABC de **impacto financeiro** dos produtos, a partir
 * das vendas reais (Degust/POS) cruzadas com o preço de custo de cadastro.
 *
 * Diferente de uma ABC só de faturamento, aqui o critério é o **lucro
 * contribuído** (faturamento − custo da mercadoria vendida). Assim um produto
 * de muito custo e pouca venda (margem baixa ou negativa) cai para o fim da
 * curva — refletindo o impacto real no resultado, não só o giro bruto.
 *
 * - `curva` (A/B/C): participação no lucro total (Pareto 80/95).
 * - `margemPct` < 0 → prejuízo (perde dinheiro a cada venda).
 * - Fallbacks: sem custo → vira ABC de faturamento; sem faturamento → volume.
 *
 * Sem dependência de React/Supabase — testável isoladamente.
 */

/** Linha de venda agregável (uma ou várias por produto). */
export interface AbcSaleRow {
  produto_master_id: number | null;
  quantidade: number | null;
  valor_total: number | null;
}

/** Classe da curva ABC. */
export type AbcCurva = 'A' | 'B' | 'C';

/** Resultado por produto. */
export interface AbcEntry {
  produto_master_id: number;
  /** Unidades vendidas no período. */
  volume: number;
  /** Faturamento (R$) no período. */
  faturamento: number;
  /** Preço de custo unitário usado (produtos_master.preco_custo). */
  custoUnit: number;
  /** Custo total da mercadoria vendida = custoUnit × volume. */
  custoTotal: number;
  /** Preço de venda médio = faturamento / volume. */
  precoVendaMedio: number;
  /** Lucro contribuído no período = faturamento − custoTotal (pode ser < 0). */
  lucro: number;
  /** Margem bruta média (%) = (venda − custo) / venda. Negativa = prejuízo. */
  margemPct: number;
  /** true quando margemPct < 0 (perde dinheiro por unidade vendida). */
  isPrejuizo: boolean;
  /** Classe A/B/C por contribuição de lucro. */
  curva: AbcCurva;
  /** Participação deste produto na métrica de classificação (%). */
  pctImpacto: number;
  /** Participação acumulada até este produto, ordenado desc (%). */
  pctAcumulado: number;
  /** Participação no faturamento total da loja (%). */
  pctFaturamento: number;
  /** Posição no ranking de impacto (1 = maior). */
  rank: number;
  /** Fração da barra (0–1) relativa ao maior |impacto| — largura visual. */
  shareOfMax: number;
}

/** Agregado completo da curva. */
export interface AbcResult {
  /** Entradas ordenadas por impacto (lucro) desc. */
  entries: AbcEntry[];
  /** Mapa produto_master_id → entrada (lookup O(1) na lista). */
  byId: Map<number, AbcEntry>;
  totalFaturamento: number;
  totalVolume: number;
  totalCusto: number;
  totalLucro: number;
  /** Contagem de produtos por classe. */
  counts: { A: number; B: number; C: number };
  /** Quantos produtos vendem com margem negativa (prejuízo). */
  prejuizoCount: number;
}

/** Limiares de corte acumulado (clássico 80/95). */
const CORTE_A = 80;
const CORTE_B = 95;

const round1 = (v: number) => Math.round(v * 10) / 10;

/**
 * Agrega vendas por produto, cruza com custo e classifica em curva ABC de lucro.
 *
 * @param rows     - Linhas de venda (Degust/POS). `produto_master_id` nulo é ignorado.
 * @param costById - Mapa produto_master_id → preço de custo unitário (opcional).
 * @returns Agregado com entradas ordenadas, mapa de lookup e totais.
 */
export function computeAbcCurve(
  rows: AbcSaleRow[],
  costById?: Map<number, number>,
): AbcResult {
  const volumeById = new Map<number, number>();
  const fatById = new Map<number, number>();

  for (const row of rows) {
    const pid = row.produto_master_id;
    if (!pid) continue;
    volumeById.set(pid, (volumeById.get(pid) || 0) + (Number(row.quantidade) || 0));
    fatById.set(pid, (fatById.get(pid) || 0) + (Number(row.valor_total) || 0));
  }

  // Derivar custo / lucro / margem por produto.
  const custoUnitById = new Map<number, number>();
  const custoTotById = new Map<number, number>();
  const lucroById = new Map<number, number>();
  const margemById = new Map<number, number>();
  const precoVendaById = new Map<number, number>();

  let totalFaturamento = 0;
  let totalVolume = 0;
  let totalCusto = 0;
  let totalLucro = 0;
  let positiveLucro = 0;

  for (const pid of volumeById.keys()) {
    const volume = volumeById.get(pid) || 0;
    const faturamento = fatById.get(pid) || 0;
    const custoUnit = costById?.get(pid) ?? 0;
    const custoTotal = custoUnit * volume;
    const lucro = faturamento - custoTotal;
    const precoVenda = volume > 0 ? faturamento / volume : 0;
    const margem = precoVenda > 0 ? ((precoVenda - custoUnit) / precoVenda) * 100 : 0;

    custoUnitById.set(pid, custoUnit);
    custoTotById.set(pid, custoTotal);
    lucroById.set(pid, lucro);
    margemById.set(pid, margem);
    precoVendaById.set(pid, precoVenda);

    totalFaturamento += faturamento;
    totalVolume += volume;
    totalCusto += custoTotal;
    totalLucro += lucro;
    if (lucro > 0) positiveLucro += lucro;
  }

  // Métrica de classificação: lucro (impacto real). Fallbacks robustos.
  const useLucro = positiveLucro > 0;
  const useFat = !useLucro && totalFaturamento > 0;
  const valueOf = (pid: number) =>
    useLucro
      ? lucroById.get(pid) || 0
      : useFat
        ? fatById.get(pid) || 0
        : volumeById.get(pid) || 0;
  const classifyTotal = useLucro
    ? positiveLucro
    : useFat
      ? totalFaturamento
      : totalVolume;

  const pids = [...volumeById.keys()].sort((a, b) => {
    const diff = valueOf(b) - valueOf(a);
    if (diff !== 0) return diff;
    return (volumeById.get(b) || 0) - (volumeById.get(a) || 0);
  });

  const maxAbs = pids.reduce((m, p) => Math.max(m, Math.abs(valueOf(p))), 0);

  const entries: AbcEntry[] = [];
  const byId = new Map<number, AbcEntry>();
  const counts = { A: 0, B: 0, C: 0 };
  let prejuizoCount = 0;
  let cumPct = 0;

  pids.forEach((pid, index) => {
    const value = valueOf(pid);
    const pct = classifyTotal > 0 && value > 0 ? (value / classifyTotal) * 100 : 0;
    cumPct += pct;

    let curva: AbcCurva;
    if (value <= 0) curva = 'C'; // contribuição nula/negativa → cauda
    else if (cumPct <= CORTE_A) curva = 'A';
    else if (cumPct <= CORTE_B) curva = 'B';
    else curva = 'C';
    counts[curva] += 1;

    const margemPct = margemById.get(pid) || 0;
    const isPrejuizo = margemPct < 0;
    if (isPrejuizo) prejuizoCount += 1;

    const faturamento = fatById.get(pid) || 0;
    const entry: AbcEntry = {
      produto_master_id: pid,
      volume: volumeById.get(pid) || 0,
      faturamento,
      custoUnit: custoUnitById.get(pid) || 0,
      custoTotal: custoTotById.get(pid) || 0,
      precoVendaMedio: precoVendaById.get(pid) || 0,
      lucro: lucroById.get(pid) || 0,
      margemPct: round1(margemPct),
      isPrejuizo,
      curva,
      pctImpacto: round1(pct),
      pctAcumulado: round1(cumPct),
      pctFaturamento:
        totalFaturamento > 0 ? round1((faturamento / totalFaturamento) * 100) : 0,
      rank: index + 1,
      shareOfMax: maxAbs > 0 ? Math.abs(value) / maxAbs : 0,
    };
    entries.push(entry);
    byId.set(pid, entry);
  });

  return {
    entries,
    byId,
    totalFaturamento,
    totalVolume,
    totalCusto,
    totalLucro,
    counts,
    prejuizoCount,
  };
}

