/**
 * @module useAbcCurve
 *
 * Hook que monta a Curva ABC de uma loja a partir das vendas reais do PDV
 * (Degust em `degust_vendas_diarias`, Linx legado em `historico_vendas`),
 * filtradas por `loja_id` e janela de período. Une as duas fontes (cada loja
 * pode ter vindo de uma origem diferente ao longo do tempo) e delega a
 * classificação ao cálculo puro `computeAbcCurve`.
 *
 * A fábrica (loja 1) não tem venda de PDV → o hook fica desabilitado e devolve
 * resultado vazio.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { computeAbcCurve, type AbcResult, type AbcSaleRow } from '../lib/abc';

// Unidades de rendimento em peso/volume: a ficha rende a granel, então
// custo ÷ rendimento dá custo por grama/ml — NÃO o CMV por unidade vendida.
// Esses produtos só entram na curva quando a ficha tiver rendimento na
// unidade de venda real (ex.: "un", "fatia", "porção").
const BULK_UNITS = new Set([
  'g',
  'kg',
  'l',
  'ml',
  'grama',
  'gramas',
  'quilo',
  'quilos',
  'kilo',
  'litro',
  'litros',
  'mililitro',
  'mililitros',
]);

const EMPTY: AbcResult = {
  entries: [],
  byId: new Map(),
  totalFaturamento: 0,
  totalVolume: 0,
  totalCusto: 0,
  totalLucro: 0,
  counts: { A: 0, B: 0, C: 0 },
  prejuizoCount: 0,
  fichaCostById: new Map(),
};

/** Pagina uma query PostgREST além do teto de 1000 linhas. */
async function fetchAll(buildRange: (from: number, to: number) => any): Promise<any[]> {
  const PAGE = 1000;
  let all: any[] = [];
  let offset = 0;
  // Limite de segurança (50 páginas = 50k linhas) — vendas de 1 loja em 90d cabem.
  for (let page = 0; page < 50; page++) {
    const { data, error } = await buildRange(offset, offset + PAGE - 1);
    if (error) throw error;
    if (!data || data.length === 0) break;
    all = all.concat(data);
    if (data.length < PAGE) break;
    offset += PAGE;
  }
  return all;
}

/**
 * Curva ABC da loja por faturamento real do período.
 *
 * @param storeId    - Loja ativa (StoreContext). 1 = Fábrica → desabilitado.
 * @param periodDays - Janela de análise em dias (default 30).
 */
export function useAbcCurve(storeId: number | null | undefined, periodDays = 30) {
  const enabled = !!storeId && storeId !== 1;

  return useQuery({
    queryKey: ['abc-curve', storeId, periodDays],
    enabled,
    staleTime: 1000 * 60 * 15,
    queryFn: async (): Promise<AbcResult> => {
      if (!storeId) return EMPTY;

      const from = new Date();
      from.setDate(from.getDate() - periodDays);
      const fromStr = from.toISOString().split('T')[0];

      const [degust, linx] = await Promise.all([
        fetchAll((a, b) =>
          supabase
            .from('degust_vendas_diarias')
            .select('produto_master_id, quantidade, valor_total')
            .eq('loja_id', storeId)
            .gte('data', fromStr)
            .not('produto_master_id', 'is', null)
            .range(a, b),
        ),
        fetchAll((a, b) =>
          supabase
            .from('historico_vendas')
            .select('produto_master_id, quantidade, valor_total')
            .eq('loja_id', storeId)
            .gte('data', fromStr)
            .not('produto_master_id', 'is', null)
            .range(a, b),
        ),
      ]);

      const rows: AbcSaleRow[] = [...degust, ...linx];

      // Custo = CMV por unidade vendida vindo da FICHA TÉCNICA construída
      // (custo_calculado ÷ rendimento_quantidade). NÃO usa o preco_custo fixo
      // antigo do cadastro. Só produtos com ficha entram na curva (requireCost).
      const pids = [
        ...new Set(rows.map((r) => r.produto_master_id).filter(Boolean)),
      ] as number[];
      const costById = new Map<number, number>();
      const bestVersao = new Map<number, number>();
      if (pids.length > 0) {
        const { data: fichas } = await supabase
          .from('fichas_tecnicas')
          .select(
            'produto_master_id, custo_calculado, rendimento_quantidade, versao, status',
          )
          .in('produto_master_id', pids)
          .gt('custo_calculado', 0)
          .gt('rendimento_quantidade', 0);
        for (const f of fichas || []) {
          const row = f as any;
          const pid = row.produto_master_id as number | null;
          if (!pid) continue;
          if ((row.status ?? '') === 'obsoleta') continue; // só ficha vigente
          const versao = Number(row.versao) || 0;
          // Mantém a maior versão por produto.
          if (bestVersao.has(pid) && versao <= (bestVersao.get(pid) as number)) {
            continue;
          }
          bestVersao.set(pid, versao);
          costById.set(
            pid,
            Number(row.custo_calculado) / Number(row.rendimento_quantidade),
          );
        }
      }

      return computeAbcCurve(rows, costById, { requireCost: true });
    },
  });
}

