// Gera o PDF de Curva ABC: por loja (atual) ou consolidado (todas as lojas),
// sempre mostrando o período considerado. Nomes vêm de produtos_master.
const handleExportAbc = async (scope: 'store' | 'all') => {
  setIsExportingAbc(true);
  try {
    let data: AbcResult;
    let storeName: string;
    let periodStart: string;
    let periodEnd: string;

    if (scope === 'all') {
      const loaded = await loadAbcCurve(RETAIL_STORE_IDS, abcPeriodDays);
      data = loaded.result;
      storeName = 'Consolidado — todas as lojas';
      periodStart = loaded.periodStart;
      periodEnd = loaded.periodEnd;
    } else {
      if (!abc) {
        toast({
          title: 'Curva ABC ainda carregando',
          variant: 'destructive',
        });
        return;
      }
      data = abc;
      storeName = selectedStore?.name ?? 'Loja';
      const to = new Date();
      const fromD = new Date();
      fromD.setDate(fromD.getDate() - abcPeriodDays);
      periodStart = fromD.toISOString().split('T')[0];
      periodEnd = to.toISOString().split('T')[0];
    }

    if (data.entries.length === 0) {
      toast({
        title: 'Sem vendas com ficha no período para gerar a Curva ABC',
        variant: 'destructive',
      });
      return;
    }

    const ids = data.entries.map((e) => e.produto_master_id);
    const { data: prods } = await supabase
      .from('produtos_master')
      .select('id, nome')
      .in('id', ids);
    const prodMap = new Map((prods || []).map((p: any) => [p.id, p]));
    const rows: AbcReportRow[] = data.entries.map((e) => ({
      nome: prodMap.get(e.produto_master_id)?.nome ?? `#${e.produto_master_id}`,
      curva: e.curva,
      volume: e.volume,
      precoCusto: e.custoUnit ?? null,
