// Preço de venda unitário fora do cardápio: o preço EXATO do PDV — a moda
// dos preços unitários diários (valor_total÷quantidade por dia), ponderada
// por volume — NÃO a média de faturamento÷volume do período, que mistura
// combos/descontos. Cardápio (vendaById) tem prioridade quando existe.
const exactPriceById = new Map<number, number>();
const priceFreq = new Map<number, Map<number, number>>();
for (const r of rows) {
  const pid = r.produto_master_id;
  const qty = Number(r.quantidade) || 0;
  const val = Number(r.valor_total) || 0;
  if (!pid || qty <= 0 || val <= 0 || vendaById.has(pid)) continue;
  const unit = Math.round((val / qty) * 100) / 100;
  if (unit <= 0) continue;
  if (!priceFreq.has(pid)) priceFreq.set(pid, new Map());
  const m = priceFreq.get(pid)!;
  m.set(unit, (m.get(unit) || 0) + qty);
}
for (const [pid, m] of priceFreq) {
  let best = 0;
  let bestW = -1;
  for (const [price, w] of m) {
    if (w > bestW || (w === bestW && price > best)) {
      bestW = w;
      best = price;
    }
  }
  if (best > 0) exactPriceById.set(pid, best);
}

const adjustedRows: AbcSaleRow[] = rows.map((r) => {
  const pid = r.produto_master_id;
  const price = pid
    ? vendaById.get(pid) ?? exactPriceById.get(pid)
    : undefined;
  if (price && price > 0) {
    return { ...r, valor_total: price * (Number(r.quantidade) || 0) };
  }
  return r;
});

