/**
 * @module useAbcCurve
 *
 * Curva ABC de impacto (lucro) a partir das vendas reais do PDV
 * (Degust em `degust_vendas_diarias`, Linx legado em `historico_vendas`).
 *
 * - Custo = CMV por unidade da **ficha técnica** (`custo_calculado ÷ rendimento`).
 *   Só produtos com ficha (rendimento em unidade vendida) entram na curva.
 * - Preço de venda = `produtos_master.preco_venda` (dos cardápios). Sobrepõe o
 *   faturamento do Degust, que é instável por kits/combos.
 *
 * `loadAbcCurve` aceita 1 loja (por-loja) ou várias (consolidado). A fábrica
 * (loja 1) não vende no PDV.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { computeAbcCurve, type AbcResult, type AbcSaleRow } from '../lib/abc';

/** Lojas de varejo (não-fábrica) para o consolidado. */
export const RETAIL_STORE_IDS = [2, 3, 4, 5, 6];

const EMPTY: AbcResult = {
  entries: [],
  byId: new Map(),
  totalFaturamento: 0,
  totalVolume: 0,
  totalCusto: 0,
  totalLucro: 0,
  counts: { A: 0, B: 0, C: 0 },
  prejuizoCount: 0,
  fichaCostById: new Map(),
};

/** Curva ABC + janela de período considerada. */
export interface AbcCurveData {
  result: AbcResult;
  /** Data inicial considerada (yyyy-mm-dd). */
  periodStart: string;
  /** Data final considerada (yyyy-mm-dd). */
  periodEnd: string;
}

/** Pagina uma query PostgREST além do teto de 1000 linhas. */
async function fetchAll(
  buildRange: (from: number, to: number) => any,
): Promise<any[]> {
  const PAGE = 1000;
  let all: any[] = [];
  let offset = 0;
  // Limite de segurança (50 páginas = 50k linhas).
  for (let page = 0; page < 50; page++) {
    const { data, error } = await buildRange(offset, offset + PAGE - 1);
    if (error) throw error;
    if (!data || data.length === 0) break;
    all = all.concat(data);
    if (data.length < PAGE) break;
    offset += PAGE;
  }
  return all;
}

/**
 * Carrega a Curva ABC para uma ou mais lojas (consolidado quando há várias).
 *
 * @param storeIds   - loja_ids a considerar. Vazio → resultado vazio.
 * @param periodDays - Janela de análise em dias.
 */
export async function loadAbcCurve(
  storeIds: number[],
  periodDays: number,
): Promise<AbcCurveData> {
  const now = new Date();
  const fromDate = new Date(now);
  fromDate.setDate(fromDate.getDate() - periodDays);
  const periodStart = fromDate.toISOString().split('T')[0];
  const periodEnd = now.toISOString().split('T')[0];

  if (storeIds.length === 0) {
    return { result: EMPTY, periodStart, periodEnd };
  }

  const [degust, linx] = await Promise.all([
    fetchAll((a, b) =>
      supabase
        .from('degust_vendas_diarias')
        .select('produto_master_id, quantidade, valor_total')
        .in('loja_id', storeIds)
        .gte('data', periodStart)
        .not('produto_master_id', 'is', null)
        .range(a, b),
    ),
    fetchAll((a, b) =>
      supabase
        .from('historico_vendas')
        .select('produto_master_id, quantidade, valor_total')
        .in('loja_id', storeIds)
        .gte('data', periodStart)
        .not('produto_master_id', 'is', null)
        .range(a, b),
    ),
  ]);

  const rows: AbcSaleRow[] = [...degust, ...linx];
  const pids = [
    ...new Set(rows.map((r) => r.produto_master_id).filter(Boolean)),
  ] as number[];

  const costById = new Map<number, number>();
  const vendaById = new Map<number, number>();

  if (pids.length > 0) {
    // CMV por unidade vendida + preço de venda já consolidados em
    // produtos_master: `cmv_unitario` é derivado das fichas com a conversão
    // correta por unidade de venda (un/fatia → custo÷rend; litro → bolinha
    // 100ml = ÷10; kg → pote 200g; etc.); `preco_venda` vem dos cardápios.
    // Colunas fora dos tipos gerados → cast.
    const { data: prods } = await (supabase as any)
      .from('produtos_master')
      .select('id, cmv_unitario, preco_venda')
      .in('id', pids);
    for (const p of prods || []) {
      const cmv = Number(p.cmv_unitario);
      if (cmv > 0) costById.set(p.id, cmv);
      const v = Number(p.preco_venda);
      if (v > 0) vendaById.set(p.id, v);
    }
  }

  // Faturamento pelo preço de cardápio (Degust é instável): preço × volume.
  const adjustedRows: AbcSaleRow[] = rows.map((r) => {
    const pid = r.produto_master_id;
    const venda = pid ? vendaById.get(pid) : undefined;
    if (venda && venda > 0) {
      return { ...r, valor_total: venda * (Number(r.quantidade) || 0) };
    }
    return r;
  });

  const result = computeAbcCurve(adjustedRows, costById, { requireCost: true });
  return { result, periodStart, periodEnd };
}

/**
 * Curva ABC reativa da loja ativa (para a lista). Fábrica (1) desabilitada.
 *
 * @param storeId    - Loja ativa (StoreContext).
 * @param periodDays - Janela de análise em dias (default 30).
 */
export function useAbcCurve(
  storeId: number | null | undefined,
  periodDays = 30,
) {
  const enabled = !!storeId && storeId !== 1;

  return useQuery({
    queryKey: ['abc-curve', storeId, periodDays],
    enabled,
    staleTime: 1000 * 60 * 15,
    queryFn: async (): Promise<AbcResult> => {
      if (!storeId) return EMPTY;
      const { result } = await loadAbcCurve([storeId], periodDays);
      return result;
    },
  });
}

