import { render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import { TooltipProvider } from '@/shared/ui/tooltip';
import { AbcBar } from './AbcBar';
import type { AbcEntry } from '../lib/abc';

const baseEntry: AbcEntry = {
  produto_master_id: 1,
  volume: 100,
  faturamento: 1400,
  custoUnit: 2,
  custoTotal: 200,
  precoVendaMedio: 14,
  lucro: 1200,
  margemPct: 86,
  isPrejuizo: false,
  curva: 'A',
  pctImpacto: 50,
  pctAcumulado: 50,
  pctFaturamento: 50,
  rank: 1,
  shareOfMax: 1,
};

const wrap = (ui: React.ReactNode) =>
  render(<TooltipProvider>{ui}</TooltipProvider>);

describe('AbcBar', () => {
  it('renderiza barra com classe, margem e infos quando tem ficha + venda', () => {
    wrap(<AbcBar entry={baseEntry} temFicha precoCusto={2} />);
    // classe (badge) e tier de lucro
    expect(screen.getByText('A')).toBeTruthy();
    expect(screen.getByText('Lucro')).toBeTruthy();
    // margem do produto
    expect(screen.getByText('86%')).toBeTruthy();
    // infos custo/venda/volume
    expect(screen.getByText('Custo')).toBeTruthy();
    expect(screen.getByText('Venda')).toBeTruthy();
    expect(screen.getByText('Vol')).toBeTruthy();
  });

  it('marca PREJUÍZO quando a margem é negativa', () => {
    wrap(
      <AbcBar
        entry={{ ...baseEntry, curva: 'C', margemPct: -10, isPrejuizo: true }}
        temFicha
      />,
    );
    expect(screen.getByText('Prejuízo')).toBeTruthy();
  });

  it('mostra "Sem ficha técnica" quando o produto não tem ficha', () => {
    wrap(<AbcBar temFicha={false} />);
    expect(screen.getByText('Sem ficha técnica')).toBeTruthy();
  });

  it('mostra "Sem venda no período" quando tem ficha mas não vendeu', () => {
    wrap(<AbcBar temFicha entry={undefined} precoCusto={2} />);
    expect(screen.getByText(/Sem venda no período/)).toBeTruthy();
  });
});

