input.new_string:
// CMV unitário + preço de venda (colunas em produtos_master fora da view).
// Carrega para TODOS os produtos exibidos — assim cuba/produzido mostra
// o CMV mesmo sem venda individual no PDV (vende como Gelato Copinho).
const idsCmv = produtosFormatados.map((p) => p.id).filter(Boolean);
if (idsCmv.length > 0) {
  const { data: cvData } = await (supabase as any)
    .from('produtos_master')
    .select('id, cmv_unitario, preco_venda')
    .in('id', idsCmv);
  const cvMap = new Map(
    (cvData || []).map((r: any) => [r.id, r]),
  );
  produtosFormatados.forEach((p) => {
    const r = cvMap.get(p.id) as any;
    if (r) {
      p.cmv_unitario =
        r.cmv_unitario != null ? Number(r.cmv_unitario) : undefined;
      p.preco_venda =
        r.preco_venda != null ? Number(r.preco_venda) : undefined;
    }
  });
}

setProdutos(produtosFormatados);
const durationMs = Math.round(performance.now() - startTime);

