alter table produtos_master add column if not exists custo_embalagem numeric;

update produtos_master set custo_embalagem = 0.14 where cmv_unitario is not null and nome ~* '^mini ' and nome !~* 'mini box|mini naked|mini caseirinho';
update produtos_master set custo_embalagem = 0.08 where cmv_unitario is not null and nome ~* 'bombom de uva';
update produtos_master set custo_embalagem = 0.15 where cmv_unitario is not null and nome ~* 'bombom de morango';
update produtos_master set custo_embalagem = 0.08 where cmv_unitario is not null and nome ~* '^brownie lowcarb';
update produtos_master set custo_embalagem = 0.63 where cmv_unitario is not null and nome ~* '^bolo pote';
update produtos_master set custo_embalagem = 2.16 where cmv_unitario is not null and (nome ~* '^doce no pote' or nome ~* '^canjica' or nome ~* '^curau');
update produtos_master set custo_embalagem = 0.71 where cmv_unitario is not null and nome ~* '^tartelete';
update produtos_master set custo_embalagem = 0.16 where cmv_unitario is not null and nome ~* '^fatia';
update produtos_master set custo_embalagem = 0.33 where cmv_unitario is not null and nome ~* '^docinho';
update produtos_master set custo_embalagem = 1.11 where cmv_unitario is not null and nome ~* 'granola';
update produtos_master set custo_embalagem = 4.35 where cmv_unitario is not null and nome ~* 'vulc';

update produtos_master set cmv_unitario = round(cmv_unitario + custo_embalagem, 2) where custo_embalagem is not null;

select count(*) produtos_com_embalagem, round(sum(custo_embalagem),2) soma_embalagem from produtos_master where custo_embalagem is not null;

update produtos_master set preco_venda = 29 where nome ilike 'canjica' or nome ilike 'curau';
select nome, preco_venda::float venda, round(cmv_unitario,2)::float cmv,
  round((preco_venda-cmv_unitario)/preco_venda*100)::int margem
from produtos_master where nome ilike 'canjica' or nome ilike 'curau' order by nome;

update produtos_master set preco_venda = 32 where nome ~* '^bolo pote' and cmv_unitario is not null;
update produtos_master set preco_venda = 30 where nome ~* '^tartelete' and cmv_unitario is not null;
update produtos_master set preco_venda = 179 where nome ~* 'vulcao chocolate c pistache';
select nome, preco_venda::float venda, round(cmv_unitario,2)::float cmv, round((preco_venda-cmv_unitario)/preco_venda*100)::int margem
from produtos_master where (nome ~* '^bolo pote' or nome ~* '^tartelete' or nome ~* 'vulcao chocolate c pistache') and cmv_unitario is not null order by nome;

update produtos_master set custo_embalagem = 16.99, cmv_unitario = round(cmv_unitario + 16.99, 2)
where cmv_unitario is not null and nome ~* '^box ' and nome !~* 'gelato';

update produtos_master set custo_embalagem = 5.36, cmv_unitario = round(cmv_unitario + 5.36, 2)
where cmv_unitario is not null and nome ~* '^mini box' and nome !~* 'gelato';

select id, nome, round(cmv_unitario,2)::float cmv_total, round(custo_embalagem,2)::float emb, preco_venda::float venda
from produtos_master
where cmv_unitario is not null and (nome ~* '^box ' or nome ~* '^mini box') and nome !~* 'gelato'
order by nome;

update produtos_master set custo_embalagem = 7.00, cmv_unitario = round(cmv_unitario + 7.00, 2)
where cmv_unitario is not null and nome ~* '^mini naked' and coalesce(custo_embalagem,0) = 0;

update produtos_master set custo_embalagem = 10.50, cmv_unitario = round(cmv_unitario + 10.50, 2)
where cmv_unitario is not null and (nome ~* '^naked p' or nome ~* 'dressed pistache p') and coalesce(custo_embalagem,0) = 0;

update produtos_master set custo_embalagem = 12.00, cmv_unitario = round(cmv_unitario + 12.00, 2)
where cmv_unitario is not null and nome ~* '^naked m' and coalesce(custo_embalagem,0) = 0;

update produtos_master set custo_embalagem = 13.50, cmv_unitario = round(cmv_unitario + 13.50, 2)
where cmv_unitario is not null and nome ~* '^naked g' and coalesce(custo_embalagem,0) = 0;

select nome, round(cmv_unitario,2)::float cmv, round(custo_embalagem,2)::float emb, preco_venda::float venda,
  case when preco_venda is not null then round((preco_venda-cmv_unitario)/preco_venda*100)::int end margem
from produtos_master where nome ~* 'naked|dressed' and cmv_unitario is not null order by cmv_unitario desc;
